// Date.now() is an absolute instant (timezone-agnostic); shifting it by IST's fixed
// +5:30 and reading it back via UTC-based methods gives correct IST wall-clock digits
// regardless of what timezone the device running this code is set to. (Previously this
// also added d.getTimezoneOffset(), which cancels the shift out entirely on any device
// already set to IST, silently making "now" run ~5.5 hours behind real IST.)
const today = () => new Date(Date.now() + 330 * 60000).toISOString().split("T")[0];
const istNow = () => new Date(Date.now() + 330 * 60000);
// Safe regardless of device timezone: getDate()/setDate() here operate as a pure
// get+set roundtrip on the same object (a translation by whole days), which is
// timezone-invariant since IST/UTC never observe DST.
const istDateAgo = (days) => { const ist = istNow(); ist.setDate(ist.getDate() - days); return ist.toISOString().split("T")[0]; };
// Must read via getUTCHours(), not getHours() — istNow()'s Date object only carries
// correct IST digits when read through UTC-based getters.
const istHour = () => istNow().getUTCHours();
// Closing Stock / Wastage are "end of day" screens — a manager opening them between
// midnight and 6AM (the cafe is shut) is almost always closing out YESTERDAY's business,
// not starting a fresh entry for the new calendar day. Default to yesterday in that
// window so a late-night submission doesn't silently land under the new date; the
// DatePicker is still right there to override.
const smartDefaultDate = () => (istHour() < 6 ? istDateAgo(1) : today());
// Morning Delivery slot's date, auto-computed — no more asking the manager to work out
// "today or tomorrow?" by hand (that manual picker is exactly what let a Sector 56
// submission at 11:48 PM land on the wrong, already-dispatched date instead of the next
// morning — see backend's POST /demands duplicate-fulfilled guard for the other half of
// this fix). The AM window is open until 11:00 IST: before that, "morning" still means
// TODAY's morning (catching up on an overnight/early submission); at or after 11:00, the
// day's morning slot has already happened, so "morning" now means the NEXT one.
const morningSlotDate = () => (istHour() < 11 ? today() : istDateAgo(-1));
// Demand windows: Night (9PM-1AM) and Day (11AM-4PM)
const getDemandWindow = () => {
  const h = istHour();
  if (h >= 21 || h < 1) return { id: "night", label: "🌙 Night Order", active: true };
  if (h >= 11 && h < 16) return { id: "day", label: "☀️ Day Order", active: true };
  return { id: "anytime", label: "📋 Manual Entry", active: true };
};
const timeNow = () => new Date().toLocaleTimeString("en-IN", { hour: "2-digit", minute: "2-digit", timeZone: "Asia/Kolkata" });

// ── Outlet daily photo module ──────────────────────────────────────────────
// 4 time-bound photos per outlet per operational day. Opening AND closing deadlines
// are per-outlet (most close 1:30 AM, GSID closes 1:00 AM). Closing runs past
// midnight, so the operational day rolls over at 5:00 AM (not midnight) — well after
// every outlet's closing and before any opening — so an after-midnight closing photo
// counts for the day that just ended, not the next. All deadlines are MINUTES from the
// op-day's own 00:00 (closing values exceed 1440 since it's the next calendar morning).
const PHOTO_OUTLET_IDS = ["sec23", "sec31", "sec56", "sec14", "gaursid"];
const OUTLET_OPENING_MIN = { sec23: 6 * 60 + 5, sec31: 7 * 60 + 5, sec56: 6 * 60 + 35, sec14: 6 * 60 + 5, gaursid: 8 * 60 + 15 };
const OUTLET_CLOSING_MIN = { gaursid: 24 * 60 + 60 }; // GSID 1:00 AM; others fall back to 1:30 AM below
const DEFAULT_CLOSING_MIN = 24 * 60 + 90;             // 1:30 AM next day
const PHOTO_OP_ROLL_MIN = 5 * 60; // 5:00 AM — operational day boundary
const OUTLET_PHOTO_TYPES = [
  { key: "opening", label: "Opening", icon: "🌅", deadline: (oid) => OUTLET_OPENING_MIN[oid] ?? (6 * 60 + 5) },
  { key: "clean", label: "Clean", icon: "🧹", deadline: () => 10 * 60 },            // 10:00 AM
  { key: "briefing", label: "Briefing", icon: "📢", deadline: () => 17 * 60 + 30 }, // 5:30 PM
  { key: "closing", label: "Closing", icon: "🌙", deadline: (oid) => OUTLET_CLOSING_MIN[oid] ?? DEFAULT_CLOSING_MIN },
];
const istMinOfDay = () => { const d = istNow(); return d.getUTCHours() * 60 + d.getUTCMinutes(); };
// Current operational date — before 5:00 AM it's still the previous calendar day.
const currentOpDate = () => (istMinOfDay() < PHOTO_OP_ROLL_MIN ? istDateAgo(1) : today());
const fmtClock = (mins) => { const mm = ((mins % 1440) + 1440) % 1440; const h = Math.floor(mm / 60), mi = mm % 60; const ap = h < 12 ? "AM" : "PM"; const h12 = h % 12 === 0 ? 12 : h % 12; return `${h12}:${String(mi).padStart(2, "0")} ${ap}`; };
// Resolve a slot's deadline from owner config (cfg[outlet][type]), else the code default.
const resolvePhotoDeadline = (cfg, outletId, typeKey) => {
  const v = cfg?.[outletId]?.[typeKey];
  if (v != null) return v;
  const t = OUTLET_PHOTO_TYPES.find((x) => x.key === typeKey);
  return t ? t.deadline(outletId) : 0;
};
// 'done' (captured) | 'expired' (deadline passed, no photo) | 'pending' (before deadline).
const outletPhotoStatus = (deadline, opDate, hasPhoto) => {
  if (hasPhoto) return "done";
  const curOp = currentOpDate();
  if (opDate < curOp) return "expired";
  if (opDate > curOp) return "pending";
  const elapsed = istMinOfDay() < PHOTO_OP_ROLL_MIN ? istMinOfDay() + 1440 : istMinOfDay();
  return elapsed > deadline ? "expired" : "pending";
};
// Clock ⇄ deadline-minutes for the owner editor. Closing in the AM (< noon) is next-day (+1440).
const minToTimeStr = (min) => { const mm = ((min % 1440) + 1440) % 1440; return `${String(Math.floor(mm / 60)).padStart(2, "0")}:${String(mm % 60).padStart(2, "0")}`; };
const timeStrToMin = (str, typeKey) => { const [h, m] = (str || "0:0").split(":").map(Number); let cm = (h || 0) * 60 + (m || 0); if (typeKey === "closing" && cm < 720) cm += 1440; return cm; };
const PHOTO_STATUS_STYLE = {
  done: { bg: "#F0FDF4", border: "#BBF7D0", color: "#16A34A" },
  expired: { bg: "#FEF2F2", border: "#FECACA", color: "#DC2626" },
  pending: { bg: "#FAFAF8", border: "#E0E0DC", color: "#999" },
};
const fmt = (n) => "₹" + Math.round(n).toLocaleString("en-IN");
const pct = (n) => (n || 0).toFixed(1) + "%";
// Mirrors the backend's normalizeDishName (salesRoutes.js) so PetPooja sales rows key
// into the same /api/recipes/costs-bulk map the server built from recipe item_names.
const normalizeDishName = (s) => (s || "").toLowerCase().trim().replace(/\.+$/, "").replace(/\s+/g, " ");
// Inverse of the backend's ingredientQtyKg (salesRoutes.js) — the should-consume
// breakdown's "per_dish" figure is always Kg-normalized (recipe_ingredients.qty_kg), but
// PATCH /recipes/ingredients/:id writes the raw `qty` column as-is in that row's own
// unit. GM/ML rows store qty as grams/mL (qty_kg = qty/1000), so a Kg value typed into
// the bulk edit form must be scaled back up before saving, or it silently lands 1000x
// too small (e.g. 0.26 Kg typed → saved as 0.26 GM instead of 260 GM).
const toNativeIngredientQty = (kgQty, unit) => {
  const u = (unit || "").trim().toUpperCase();
  return ["GM", "G", "GMS", "GRAM", "GRAMS", "ML"].includes(u) ? kgQty * 1000 : kgQty;
};

