// ═════════════════════════════════════════════════════════════════════════════
//  USERS MANAGEMENT
// ═════════════════════════════════════════════════════════════════════════════
const ROLE_OPTIONS = [
  { v: "outlet_mgr", l: "🏪 Outlet" }, { v: "chef", l: "👨‍🍳 Chef" }, { v: "bainmarry", l: "🍲 Bainmarry" },
  { v: "store_mgr", l: "📦 Store" }, { v: "owner", l: "👑 Owner" }, { v: "driver", l: "🚚 Driver" },
  { v: "avp", l: "🧭 AVP" }, { v: "head_chef", l: "🧑‍🍳 Head Chef" }, { v: "bk_manager", l: "🏭 BK Manager" },
  { v: "franchise", l: "🤝 Franchise" },
];
// Roles whose account is tied to exactly one outlet (an outlet_id must be assigned).
const OUTLET_SCOPED_ROLES_FE = ["outlet_mgr", "chef", "bainmarry", "franchise"];
// Extra cross-cutting duties assignable ON TOP of a user's base role (app_users.responsibilities).
// 'cogs' gives an outlet manager cross-outlet COGS oversight (Flags + COGS Compare + Sales)
// while they stay pinned to their own outlet for everything else. Add more here as needed.
const RESPONSIBILITY_OPTIONS = [
  { v: "cogs", l: "📊 COGS Oversight", hint: "Flags, COGS Compare & Sales — all outlets" },
  { v: "onboarding", l: "🧑‍💼 Onboarding", hint: "Add & manage team across ALL outlets + offer letters" },
  { v: "reviews", l: "⭐ Reviews", hint: "Daily Review & Rating Summary — all outlets" },
];
const UsersPanel = () => {
  const [users, setUsers] = useState([]);
  const [loading, setLoading] = useState(true);
  const [showAdd, setShowAdd] = useState(false);
  const [newName, setNewName] = useState("");
  const [newPhone, setNewPhone] = useState("");
  const [newRole, setNewRole] = useState("outlet_mgr");
  const [newOutlet, setNewOutlet] = useState("");
  const [saving, setSaving] = useState(false);
  const [editPinId, setEditPinId] = useState(null);
  const [editPinVal, setEditPinVal] = useState("");
  // A role switch that can't be saved yet because the target role is outlet-scoped but the
  // user has no outlet assigned (e.g. an AVP → Outlet Manager). Held here (user id -> role)
  // so the outlet dropdown appears and role+outlet commit together — otherwise the backend
  // rightly rejects an outlet_mgr with no outlet and the switch gets stuck.
  const [pendingRole, setPendingRole] = useState({});

  const load = () => { api.getUsers().then(setUsers).catch(() => {}).finally(() => setLoading(false)); };
  useEffect(load, []);

  const addUser = async () => {
    if (!newName || !newPhone) { alert("Name and phone required"); return; }
    // An outlet-scoped role with no outlet picked used to silently create an
    // account that could see/edit every outlet's employees instead of just its
    // own (the department filter in employees.js treats "no outlet" the same
    // as "unrestricted owner") — catch it here before it ever reaches the API.
    if (OUTLET_SCOPED_ROLES_FE.includes(newRole) && !newOutlet) { alert("Please select an outlet for this role"); return; }
    setSaving(true);
    try {
      await api.createUser({ name: newName, phone: newPhone, role: newRole, outlet_id: newOutlet || null });
      setNewName(""); setNewPhone(""); setNewRole("outlet_mgr"); setNewOutlet(""); setShowAdd(false);
      load();
    } catch (e) { alert("Error: " + e.message); }
    finally { setSaving(false); }
  };

  const savePin = async (id) => {
    if (editPinVal.length !== 4) { alert("PIN must be 4 digits"); return; }
    try {
      await api.updateUser(id, { reset_pin: false, pin: editPinVal });
      setEditPinId(null); setEditPinVal("");
      load();
    } catch (e) { alert("Error: " + e.message); }
  };

  const toggleActive = async (id, active) => {
    try { await api.updateUser(id, { active: !active }); load(); } catch (e) { alert("Error: " + e.message); }
  };

  const clearPending = (id) => setPendingRole((p) => { const n = { ...p }; delete n[id]; return n; });

  const changeRole = async (u, newRole) => {
    if (newRole === u.role) { clearPending(u.id); return; }
    const outletScoped = OUTLET_SCOPED_ROLES_FE.includes(newRole);
    // Switching to an outlet-scoped role but no outlet assigned yet → don't save now.
    // Hold the switch as pending so the outlet dropdown appears; it commits role+outlet
    // together once an outlet is picked (see the outlet <select> below). Without this the
    // backend rejects the outlet_mgr (no outlet) and the role never actually changes.
    if (outletScoped && !u.outlet_id) { setPendingRole((p) => ({ ...p, [u.id]: newRole })); return; }
    try {
      // Outlet assignment only makes sense for outlet-scoped roles — clear it when
      // switching to a cross-outlet role so a stale outlet_id doesn't linger.
      await api.updateUser(u.id, { role: newRole, ...(outletScoped ? {} : { outlet_id: null }) });
      clearPending(u.id);
      load();
    } catch (e) { alert("Error: " + e.message); }
  };

  // Toggle one extra responsibility on/off for a user — sends the full resulting array
  // (the backend replaces the column wholesale). Takes effect on their next login/request.
  const toggleResp = async (u, respV) => {
    const cur = Array.isArray(u.responsibilities) ? u.responsibilities : [];
    const next = cur.includes(respV) ? cur.filter((r) => r !== respV) : [...cur, respV];
    try { await api.updateUser(u.id, { responsibilities: next }); load(); }
    catch (e) { alert("Error: " + e.message); }
  };

  if (loading) return <div style={{ textAlign: "center", padding: 40, color: "#999" }}>⏳ Loading...</div>;

  const roleLabel = (r) => r === "owner" ? "👑 Owner" : r === "store_mgr" ? "📦 Store" : r === "driver" ? "🚚 Driver" : r === "chef" ? "👨‍🍳 Chef" : r === "bainmarry" ? "🍲 Bainmarry" : r === "avp" ? "🧭 AVP" : r === "head_chef" ? "🧑‍🍳 Head Chef" : r === "bk_manager" ? "🏭 BK Manager" : r === "franchise" ? "🤝 Franchise" : r === "shift_manager" ? "⭐ Shift Manager" : "🏪 Outlet";
  const outletLabel = (id) => OUTLETS.find(o => o.id === id)?.name || id || "—";

  return (<div>
    <div style={{ display: "flex", alignItems: "center", gap: 10, marginBottom: 16 }}>
      <h3 style={{ fontSize: 16, fontWeight: 800, margin: 0, flex: 1 }}>👥 Users ({users.length})</h3>
      <button onClick={() => setShowAdd(!showAdd)} style={{ padding: "6px 14px", borderRadius: 8, border: "none", background: "#1A1A1A", color: "#fff", fontWeight: 700, fontSize: 12, cursor: "pointer", fontFamily: "inherit" }}>+ Add User</button>
    </div>

    {showAdd && <div style={{ background: "#fff", borderRadius: 14, border: "1px solid #E8E8E4", padding: "16px", marginBottom: 16 }}>
      <input placeholder="Name" value={newName} onChange={(e) => setNewName(e.target.value)} style={{ width: "100%", padding: "10px 14px", borderRadius: 10, border: "1px solid #E0E0DC", fontSize: 14, fontFamily: "inherit", marginBottom: 8, boxSizing: "border-box" }} />
      <input type="tel" placeholder="Phone (10 digits)" value={newPhone} onChange={(e) => setNewPhone(e.target.value.replace(/\D/g, "").slice(0, 10))} style={{ width: "100%", padding: "10px 14px", borderRadius: 10, border: "1px solid #E0E0DC", fontSize: 14, fontFamily: "inherit", marginBottom: 8, boxSizing: "border-box" }} />
      <div style={{ display: "flex", gap: 6, marginBottom: 8, flexWrap: "wrap" }}>
        {ROLE_OPTIONS.map(r => (
          <button key={r.v} onClick={() => setNewRole(r.v)} style={{ flex: "1 1 30%", padding: "8px", borderRadius: 8, border: newRole === r.v ? "none" : "1px solid #E0E0DC", background: newRole === r.v ? "#1A1A1A" : "#fff", color: newRole === r.v ? "#fff" : "#888", fontWeight: 600, fontSize: 12, cursor: "pointer", fontFamily: "inherit" }}>{r.l}</button>
        ))}
      </div>
      {OUTLET_SCOPED_ROLES_FE.includes(newRole) && <select value={newOutlet} onChange={(e) => setNewOutlet(e.target.value)} style={{ width: "100%", padding: "10px 14px", borderRadius: 10, border: "1px solid #E0E0DC", fontSize: 14, fontFamily: "inherit", marginBottom: 8, boxSizing: "border-box" }}>
        <option value="">Select Outlet</option>
        {(newRole === "franchise" ? OUTLETS.filter(o => o.franchise) : OUTLETS).map(o => <option key={o.id} value={o.id}>{o.name}</option>)}
      </select>}
      <button onClick={addUser} disabled={saving} style={{ width: "100%", padding: "12px", borderRadius: 12, border: "none", background: "#16A34A", color: "#fff", fontWeight: 800, fontSize: 14, cursor: "pointer", fontFamily: "inherit" }}>{saving ? "⏳..." : "✅ Create User (PIN auto-generated)"}</button>
    </div>}

    {users.map(u => (
      <div key={u.id} style={{ background: "#fff", borderRadius: 12, border: "1px solid #E8E8E4", padding: "14px 16px", marginBottom: 8, opacity: u.active ? 1 : 0.5 }}>
        <div style={{ display: "flex", alignItems: "center", gap: 10 }}>
          <div style={{ flex: 1 }}>
            <div style={{ fontSize: 14, fontWeight: 700 }}>{u.name}</div>
            <div style={{ fontSize: 12, color: "#888" }}>{u.phone} · {roleLabel(u.role)}</div>
          </div>
          {editPinId === u.id ? (
            <div style={{ display: "flex", alignItems: "center", gap: 4 }}>
              <input type="tel" inputMode="numeric" value={editPinVal} onChange={(e) => setEditPinVal(e.target.value.replace(/\D/g, "").slice(0, 4))} autoFocus
                style={{ width: 70, fontSize: 18, fontWeight: 800, fontFamily: "'JetBrains Mono'", textAlign: "center", letterSpacing: 4, padding: "4px", borderRadius: 6, border: "2px solid #2563EB", color: "#2563EB" }} />
              <button onClick={() => savePin(u.id)} disabled={editPinVal.length !== 4} style={{ padding: "4px 8px", borderRadius: 6, border: "none", background: editPinVal.length === 4 ? "#16A34A" : "#D0D0CC", color: "#fff", fontWeight: 700, fontSize: 11, cursor: editPinVal.length === 4 ? "pointer" : "not-allowed", fontFamily: "inherit" }}>✓</button>
              <button onClick={() => { setEditPinId(null); setEditPinVal(""); }} style={{ padding: "4px 8px", borderRadius: 6, border: "none", background: "#F5F5F3", color: "#888", fontWeight: 700, fontSize: 11, cursor: "pointer", fontFamily: "inherit" }}>✕</button>
            </div>
          ) : (
            <span onClick={() => { setEditPinId(u.id); setEditPinVal(u.pin); }} style={{ fontFamily: "'JetBrains Mono'", fontSize: 18, fontWeight: 800, color: "#2563EB", letterSpacing: 4, cursor: "pointer" }} title="Tap to edit PIN">{u.pin}</span>
          )}
        </div>
        <div style={{ marginTop: 8 }}>
          <select value={pendingRole[u.id] ?? u.role} onChange={(e) => changeRole(u, e.target.value)}
            style={{ width: "100%", padding: "8px 10px", borderRadius: 8, border: pendingRole[u.id] ? "1px solid #B45309" : "1px solid #E0E0DC", fontSize: 12, fontFamily: "inherit", color: "#1A1A1A", fontWeight: 600 }}>
            {ROLE_OPTIONS.map(r => <option key={r.v} value={r.v}>{r.l}</option>)}
          </select>
        </div>
        {/* Outlet assignment for outlet managers, chefs, bainmarry staff, and franchise
            partners. Also shown for a PENDING switch into one of these roles (effectiveRole),
            so an outlet-less user can pick an outlet to complete the switch — role+outlet
            then commit together in one update. */}
        {(() => {
          const effectiveRole = pendingRole[u.id] ?? u.role;
          if (!OUTLET_SCOPED_ROLES_FE.includes(effectiveRole)) return null;
          const isPending = !!pendingRole[u.id];
          return (
            <div style={{ marginTop: 8 }}>
              {isPending && <div style={{ fontSize: 11, color: "#B45309", fontWeight: 600, marginBottom: 4 }}>⚠️ Pick an outlet to finish switching to {ROLE_OPTIONS.find(r => r.v === effectiveRole)?.l || effectiveRole}</div>}
              <select value={isPending ? "" : (u.outlet_id || "")}
                onChange={async (e) => {
                  const outlet_id = e.target.value || null;
                  if (isPending && !outlet_id) return; // an outlet-scoped role can't be saved with no outlet
                  try {
                    await api.updateUser(u.id, { ...(isPending ? { role: effectiveRole } : {}), outlet_id });
                    clearPending(u.id);
                    load();
                  } catch (err) { alert("Error: " + err.message); }
                }}
                style={{ width: "100%", padding: "8px 10px", borderRadius: 8, border: isPending ? "1px solid #B45309" : "1px solid #E0E0DC", fontSize: 12, fontFamily: "inherit", color: (!isPending && u.outlet_id) ? "#1A1A1A" : "#999", fontWeight: 600 }}>
                <option value="">No outlet assigned</option>
                {(effectiveRole === "franchise" ? OUTLETS.filter(o => o.franchise) : OUTLETS).map(o => <option key={o.id} value={o.id}>{o.name}</option>)}
              </select>
            </div>
          );
        })()}
        {/* Extra responsibilities on top of the base role — e.g. an outlet manager also given
            cross-outlet COGS oversight. Independent of role/outlet; a manager stays pinned to
            their own outlet for everything except what the responsibility explicitly opens up. */}
        <div style={{ marginTop: 8 }}>
          <div style={{ fontSize: 10, color: "#999", fontWeight: 700, marginBottom: 4 }}>EXTRA RESPONSIBILITIES</div>
          {RESPONSIBILITY_OPTIONS.map((r) => {
            const on = Array.isArray(u.responsibilities) && u.responsibilities.includes(r.v);
            return (
              <label key={r.v} style={{ display: "flex", alignItems: "center", gap: 8, padding: "6px 8px", borderRadius: 8, border: `1px solid ${on ? "#BFDBFE" : "#E0E0DC"}`, background: on ? "#EFF6FF" : "#fff", cursor: "pointer", marginBottom: 4 }}>
                <input type="checkbox" checked={on} onChange={() => toggleResp(u, r.v)} />
                <span style={{ fontSize: 12, fontWeight: 600 }}>{r.l}</span>
                <span style={{ fontSize: 10, color: "#999" }}>{r.hint}</span>
              </label>
            );
          })}
        </div>
        <div style={{ display: "flex", gap: 8, marginTop: 10 }}>
          <button onClick={() => { setEditPinId(u.id); setEditPinVal(u.pin); }} style={{ flex: 1, padding: "6px", borderRadius: 6, border: "1px solid #BFDBFE", background: "#EFF6FF", color: "#2563EB", fontWeight: 600, fontSize: 11, cursor: "pointer", fontFamily: "inherit" }}>✏️ Change PIN</button>
          <button onClick={() => toggleActive(u.id, u.active)} style={{ flex: 1, padding: "6px", borderRadius: 6, border: `1px solid ${u.active ? "#FECACA" : "#BBF7D0"}`, background: u.active ? "#FEF2F2" : "#F0FDF4", color: u.active ? "#DC2626" : "#16A34A", fontWeight: 600, fontSize: 11, cursor: "pointer", fontFamily: "inherit" }}>{u.active ? "🚫 Disable" : "✅ Enable"}</button>
        </div>
      </div>
    ))}
  </div>);
};

// ═════════════════════════════════════════════════════════════════════════════
//  EMPLOYEE MASTER — mini HRMS: full staff directory (employee code, salary,
//  shift/roster timing, bank/UPI details), grouped by Outlet / Base Kitchen /
//  Top Management, plus per-employee daily attendance marking. Superset of
//  UsersPanel's app_users — covers staff who never log into the app (helpers,
//  cooks, cleaners), and can optionally link to an app_users row for those who
//  do. Staff advances are NOT duplicated here — they stay tracked in Books
//  Ledger (books_ledger.employee_id) and this panel just shows the resulting
//  outstanding balance per employee.
// ═════════════════════════════════════════════════════════════════════════════
const EMPLOYEE_DEPARTMENTS = [
  ...OUTLETS.map(o => ({ id: o.id, label: `🏪 ${o.name}` })),
  { id: "bk", label: "🏭 Base Kitchen" },
  { id: "top_mgmt", label: "👑 Top Management" },
];
// Roster (DOD → Roster) — shared with the outlet-manager Team cards so both show the same
// position/shift/break, assigned centrally by the owner.
const ROSTER_POSITIONS = ["Manager", "Chef", "Bainmarry", "Helper", "House Keeping", "Other"];
const ROSTER_SHIFTS = [{ v: "", l: "— Unassigned" }, { v: "morning", l: "🌅 Morning" }, { v: "evening", l: "🌙 Evening" }];
const rosterShiftLabel = (v) => ROSTER_SHIFTS.find((s) => s.v === (v || ""))?.l || "— Unassigned";
// Best-guess position from the free-text designation, used until one is explicitly set.
const deriveRosterPosition = (desig) => {
  const d = (desig || "").toLowerCase();
  if (/manager/.test(d)) return "Manager";
  if (/chef/.test(d)) return "Chef";
  if (/bain|bamb|banmarr/.test(d)) return "Bainmarry";
  if (/house ?keep|housekeep/.test(d)) return "House Keeping";
  if (/helper/.test(d)) return "Helper";
  return "Other";
};
const effectiveRosterPosition = (e) => e.position || deriveRosterPosition(e.designation);
// 12-hour clock labels for the break-window start/end pickers → "12am".."11pm".
const ROSTER_TIME_OPTS = Array.from({ length: 24 }, (_, h) => `${h % 12 === 0 ? 12 : h % 12}${h < 12 ? "am" : "pm"}`);
const SALARY_TYPES = [{ v: "monthly", l: "Monthly" }, { v: "daily", l: "Daily" }];
const WEEKDAYS = ["Monday", "Tuesday", "Wednesday", "Thursday", "Friday", "Saturday", "Sunday"];
const EMPLOYEE_FORM_DEFAULTS = {
  name: "", designation: "", department: EMPLOYEE_DEPARTMENTS[0].id, phone: "", joining_date: "", app_user_id: "",
  salary: "", salary_type: "monthly", leave_allowed: "", shift_start: "", shift_end: "", weekly_off: "",
  bank_account_name: "", bank_account_number: "", bank_ifsc: "", upi_id: "",
};
const employeeFormToPayload = (f) => ({
  name: f.name, designation: f.designation, department: f.department,
  phone: f.phone || null, joining_date: f.joining_date || null, app_user_id: f.app_user_id || null,
  salary: f.salary === "" ? null : Number(f.salary), salary_type: f.salary_type,
  leave_allowed: f.leave_allowed === "" ? 0 : Number(f.leave_allowed),
  shift_start: f.shift_start || null, shift_end: f.shift_end || null, weekly_off: f.weekly_off || null,
  bank_account_name: f.bank_account_name || null, bank_account_number: f.bank_account_number || null,
  bank_ifsc: f.bank_ifsc || null, upi_id: f.upi_id || null,
});

// Daily attendance grid for one employee — tap a day to cycle through
// present → absent → half-day → leave → (cleared). One month at a time.
const ATTENDANCE_STATUS_CYCLE = ["present", "absent", "half_day", "leave"];
const ATTENDANCE_STYLE = {
  present: { l: "P", bg: "#DCFCE7", color: "#16A34A" },
  absent: { l: "A", bg: "#FEE2E2", color: "#DC2626" },
  half_day: { l: "½", bg: "#FEF3C7", color: "#B45309" },
  leave: { l: "L", bg: "#DBEAFE", color: "#2563EB" },
};
const EmployeeAttendance = ({ employee }) => {
  const [month, setMonth] = useState(() => today().slice(0, 7));
  const [records, setRecords] = useState({}); // date -> attendance row
  const [loading, setLoading] = useState(true);

  const daysInMonth = new Date(Number(month.slice(0, 4)), Number(month.slice(5, 7)), 0).getDate();
  const from = `${month}-01`;
  const to = `${month}-${String(daysInMonth).padStart(2, "0")}`;

  const load = useCallback(() => {
    setLoading(true);
    api.getAttendance({ employee_id: employee.id, from, to })
      .then((rows) => { const map = {}; rows.forEach((r) => { map[r.date] = r; }); setRecords(map); })
      .catch(() => setRecords({}))
      .finally(() => setLoading(false));
  }, [employee.id, from, to]);
  useEffect(load, [load]);

  const cycle = async (date) => {
    const existing = records[date];
    const idx = existing ? ATTENDANCE_STATUS_CYCLE.indexOf(existing.status) : -1;
    if (idx === ATTENDANCE_STATUS_CYCLE.length - 1) {
      try { await api.deleteAttendance(existing.id); } catch (e) { alert("Error: " + e.message); return; }
      setRecords((p) => { const n = { ...p }; delete n[date]; return n; });
      return;
    }
    const nextStatus = ATTENDANCE_STATUS_CYCLE[idx + 1];
    try {
      const saved = await api.markAttendance({ employee_id: employee.id, date, status: nextStatus });
      setRecords((p) => ({ ...p, [date]: saved }));
    } catch (e) { alert("Error: " + e.message); }
  };

  const counts = ATTENDANCE_STATUS_CYCLE.reduce((acc, s) => { acc[s] = Object.values(records).filter((r) => r.status === s).length; return acc; }, {});

  return (<div style={{ marginTop: 10, paddingTop: 10, borderTop: "1px solid #F0F0EC" }}>
    <div style={{ display: "flex", alignItems: "center", gap: 8, marginBottom: 8 }}>
      <button onClick={() => { const d = new Date(month + "-01"); d.setMonth(d.getMonth() - 1); setMonth(d.toISOString().slice(0, 7)); }} style={{ padding: "3px 8px", borderRadius: 6, border: "1px solid #E0E0DC", background: "#fff", cursor: "pointer", fontFamily: "inherit", fontSize: 12 }}>←</button>
      <span style={{ fontSize: 12, fontWeight: 700, flex: 1, textAlign: "center" }}>{month}</span>
      <button onClick={() => { const d = new Date(month + "-01"); d.setMonth(d.getMonth() + 1); setMonth(d.toISOString().slice(0, 7)); }} style={{ padding: "3px 8px", borderRadius: 6, border: "1px solid #E0E0DC", background: "#fff", cursor: "pointer", fontFamily: "inherit", fontSize: 12 }}>→</button>
    </div>
    {loading ? <div style={{ fontSize: 11, color: "#999", textAlign: "center", padding: 10 }}>⏳ Loading...</div> : (<>
      <div style={{ display: "flex", flexWrap: "wrap", gap: 4, marginBottom: 8 }}>
        {Array.from({ length: daysInMonth }, (_, i) => i + 1).map((day) => {
          const date = `${month}-${String(day).padStart(2, "0")}`;
          const rec = records[date];
          const style = rec ? ATTENDANCE_STYLE[rec.status] : null;
          return (
            <button key={day} onClick={() => cycle(date)} title={rec ? `${date}: ${rec.status.replace("_", " ")}` : `${date}: tap to mark`}
              style={{ width: 27, height: 27, borderRadius: 6, border: style ? "none" : "1px solid #E8E8E4", background: style ? style.bg : "#FAFAF8", color: style ? style.color : "#BBB", fontSize: 10, fontWeight: 800, cursor: "pointer", fontFamily: "inherit" }}>
              {style ? style.l : day}
            </button>
          );
        })}
      </div>
      <div style={{ display: "flex", gap: 10, fontSize: 10, color: "#888", flexWrap: "wrap" }}>
        <span>🟢 {counts.present} present</span>
        <span>🔴 {counts.absent} absent</span>
        <span>🟡 {counts.half_day} half-day</span>
        <span>🔵 {counts.leave} leave</span>
      </div>
    </>)}
  </div>);
};

