// ─── Print helper ───────────────────────────────────────────────────────────
const printSection = (sectionId, title) => {
  const el = document.getElementById(sectionId); if (!el) return;
  const pw = window.open("", "_blank");
  const ds = new Date().toLocaleDateString("en-IN", { weekday: "long", day: "numeric", month: "short", year: "numeric", timeZone: "Asia/Kolkata" });
  pw.document.write(`<!DOCTYPE html><html><head><title>${title}</title><link href="https://fonts.googleapis.com/css2?family=Outfit:wght@300;400;500;600;700;800&family=JetBrains+Mono:wght@400;500;600;700&display=swap" rel="stylesheet" /><style>*{box-sizing:border-box;margin:0;padding:0}body{font-family:'Outfit',sans-serif;color:#1A1A1A;padding:24px;background:#fff}.print-header{display:flex;justify-content:space-between;align-items:center;border-bottom:2px solid #1A1A1A;padding-bottom:12px;margin-bottom:20px}.print-header h1{font-size:18px;font-weight:800}.print-header span{font-size:12px;color:#888}table{width:100%;border-collapse:collapse;font-size:12px}th{padding:8px 10px;text-align:left;font-size:10px;font-weight:700;color:#666;text-transform:uppercase;border-bottom:2px solid #DDD;background:#F8F8F5}td{padding:8px 10px;border-bottom:1px solid #EEE}.no-print,button,input{display:none!important}@media print{body{padding:0}}</style></head><body><div class="print-header"><h1>The The Ananda Cafe — ${title}</h1><span>${ds}</span></div>${el.innerHTML}</body></html>`);
  pw.document.close(); setTimeout(() => { pw.focus(); pw.print(); }, 400);
};
const PrintBtn = ({ sectionId, title }) => (
  <button className="no-print" onClick={() => printSection(sectionId, title)} style={{ display: "inline-flex", alignItems: "center", gap: 5, padding: "6px 14px", borderRadius: 8, border: "1px solid #E0E0DC", background: "#fff", fontSize: 12, fontWeight: 600, color: "#777", cursor: "pointer", fontFamily: "inherit" }}>🖨️ Print</button>
);

// ─── CSV Export helper ──────────────────────────────────────────────────────
const exportCSV = (headers, rows, filename) => {
  const csv = [headers.join(","), ...rows.map((r) => r.map((c) => `"${String(c ?? "").replace(/"/g, '""')}"`).join(","))].join("\n");
  const blob = new Blob([csv], { type: "text/csv" });
  const url = URL.createObjectURL(blob);
  const a = document.createElement("a"); a.href = url; a.download = filename; a.click();
  URL.revokeObjectURL(url);
};
const ExportBtn = ({ onClick }) => (
  <button className="no-print" onClick={onClick} style={{ display: "inline-flex", alignItems: "center", gap: 5, padding: "6px 14px", borderRadius: 8, border: "1px solid #BBF7D0", background: "#F0FDF4", fontSize: 12, fontWeight: 600, color: "#16A34A", cursor: "pointer", fontFamily: "inherit" }}>📥 CSV</button>
);

// ═════════════════════════════════════════════════════════════════════════════
//  BASE KITCHEN (Consolidated Demand + Stock Out BK + Per-Outlet Direct Items)
// ═════════════════════════════════════════════════════════════════════════════
const BaseKitchen = () => {
  const [orders, setOrders] = useState([]); const [prevDayOrders, setPrevDayOrders] = useState([]);
  const [loading, setLoading] = useState(true);
  const [selDate, setSelDate] = useState(today());
  const [showAll, setShowAll] = useState(false);
  const [cycle, setCycle] = useState("all"); // all, morning, evening
  const [stockOutFilter, setStockOutFilter] = useState("bk");
  // Staff Food/Dress requests — outlets submit these separately (staff_demands table,
  // not the regular demands table BK_ITEMS/consolidated below reads from), so BK needs
  // its own fetch to see them at all. Keyed off the same selDate as everything else here.
  const [staffDemands, setStaffDemands] = useState([]);
  const [staffMasterItems, setStaffMasterItems] = useState([]);
  useEffect(() => {
    Promise.all([api.getStaffDemands({ date: selDate }), api.getStaffDemandItems()])
      .then(([sd, si]) => { setStaffDemands(sd || []); setStaffMasterItems(si || []); })
      .catch(() => { setStaffDemands([]); setStaffMasterItems([]); });
  }, [selDate]);
  // Each outlet's own closing stock from the day BEFORE selDate — i.e. what's actually
  // sitting there right now, before today's demand gets fulfilled — shown alongside
  // demand in the Consolidated Demand table below so BK can see at a glance whether an
  // outlet already has stock on hand before dispatching more of it. selDate's OWN closing
  // stock doesn't exist yet at demand time (it's only submitted at the end of that same
  // day), which is why this reads the prior day instead. Draft (not-yet-finalized)
  // closing stock isn't counted, same "not reliable yet" rule every other closing-stock
  // read in this app already follows.
  const [closingStocksByOutlet, setClosingStocksByOutlet] = useState({});
  useEffect(() => {
    const [y, m, d] = selDate.split("-").map(Number);
    const prevDate = new Date(Date.UTC(y, m - 1, d));
    prevDate.setUTCDate(prevDate.getUTCDate() - 1);
    const prevDateStr = prevDate.toISOString().split("T")[0];
    api.getClosingStocks({ date: prevDateStr }).then((rows) => {
      const byOutlet = {};
      (rows || []).filter((r) => r.status === "submitted").forEach((r) => { byOutlet[r.outlet_id] = r.items || {}; });
      setClosingStocksByOutlet(byOutlet);
    }).catch(() => setClosingStocksByOutlet({}));
  }, [selDate]);
  const load = useCallback(() => {
    setLoading(true);
    // Load today's orders AND previous day's orders (for night demands)
    const prevDate = istDateAgo(1);
    Promise.all([
      api.getOrders({ date: selDate }),
      selDate === today() ? api.getOrders({ date: prevDate }) : Promise.resolve([]),
    ]).then(([todayData, prevData]) => {
      setOrders(todayData.filter((d) => d.type === "manual" && d.items));
      setPrevDayOrders(prevData.filter((d) => d.type === "manual" && d.items));
    }).catch(() => { setOrders([]); setPrevDayOrders([]); }).finally(() => setLoading(false));
  }, [selDate]);
  useEffect(load, [load]);

  // Split orders into morning and evening cycles using demand_slot field
  // Fallback to submission time if demand_slot is not set (old orders)
  const getOrderHour = (o) => {
    if (!o.submitted_at) return 12;
    const d = new Date(o.submitted_at);
    const ist = new Date(d.getTime() + 330 * 60000);
    return ist.getUTCHours();
  };

  const morningOrders = [
    ...orders.filter((o) => o.demand_slot === "morning"),
    // Fallback for old orders without demand_slot: night submissions
    ...prevDayOrders.filter((o) => !o.demand_slot && getOrderHour(o) >= 21),
    ...orders.filter((o) => !o.demand_slot && getOrderHour(o) < 1),
  ];
  const eveningOrders = [
    ...orders.filter((o) => o.demand_slot === "evening"),
    // Fallback for old orders without demand_slot: day submissions
    ...orders.filter((o) => !o.demand_slot && getOrderHour(o) >= 1),
  ];

  const cycleOrders = cycle === "morning" ? morningOrders : cycle === "evening" ? eveningOrders : orders;

  const pendingOrders = cycleOrders.filter((o) => o.status === "submitted" || o.status === "received");
  const dispatchedOrders = cycleOrders.filter((o) => o.status === "fulfilled");
  const issuedOrders = cycleOrders.filter((o) => o.status === "issued");
  const activeOrders = showAll ? cycleOrders : pendingOrders;

  // Batter items always consolidate into Kg (bkDisplayUnit), everything else into its
  // own catalog unit — normalizeUnit handles both a straight Kg entry (post-Aug-11) and
  // a legacy Batch entry (no items_units stamped) correctly either way, converting
  // whichever one doesn't already match the target.
  const consolidated = {}; BK_ITEMS.forEach((bk) => { consolidated[bk.id] = { total: 0, by: {} }; const targetUnit = bkDisplayUnit(bk.id, bk.unit); activeOrders.forEach((o) => { const q = normalizeUnit(bk.id, o.items?.[bk.id] || 0, o.items_units?.[bk.id], targetUnit); consolidated[bk.id].total += q; consolidated[bk.id].by[o.outlet_id] = (consolidated[bk.id].by[o.outlet_id] || 0) + q; }); });

  const foodSection = DEMAND_SECTIONS.find((s) => s.id === "food");
  const foodItemIds = new Set(foodSection?.items.map((i) => i.id) || []);
  const rawReq = {};
  Object.entries(consolidated).forEach(([bkId, data]) => {
    if (!foodItemIds.has(bkId)) return;
    const recipe = RECIPES[bkId]; if (!recipe || data.total === 0) return;
    const batches = data.total / recipe.yieldQty;
    recipe.ingredients.forEach((ing) => { rawReq[ing.rawId] = (rawReq[ing.rawId] || 0) + ing.qty * batches; });
  });

  const nonFoodSections = DEMAND_SECTIONS.filter((s) => s.id !== "food");
  const directItems = {}; const allDirectItems = {};
  activeOrders.forEach((o) => {
    if (!directItems[o.outlet_id]) directItems[o.outlet_id] = {};
    nonFoodSections.forEach((sec) => { sec.items.forEach((item) => {
      const qty = o.items?.[item.id] || 0;
      if (qty > 0) {
        if (!directItems[o.outlet_id][item.id]) directItems[o.outlet_id][item.id] = { name: item.name, qty: 0, unit: item.unit || "", category: sec.titleHi };
        directItems[o.outlet_id][item.id].qty += qty;
        if (!allDirectItems[item.id]) allDirectItems[item.id] = { name: item.name, qty: 0, unit: item.unit || "", category: sec.titleHi };
        allDirectItems[item.id].qty += qty;
      }
    }); });
  });

  const stockOutItems = stockOutFilter === "bk" ? null : stockOutFilter === "all" ? allDirectItems : (directItems[stockOutFilter] || {});
  const hasRawReq = Object.keys(rawReq).length > 0;

  const staffItemName = (id) => staffMasterItems.find((i) => i.id === id)?.name || id;
  const staffItemUnit = (id) => staffMasterItems.find((i) => i.id === id)?.unit || "";
  const foodDemands = staffDemands.filter((d) => d.category === "food");
  const dressDemands = staffDemands.filter((d) => d.category === "dress");
  const staffFoodConsolidated = {}; // item id -> { total, by: { outlet_id: qty } }
  foodDemands.forEach((d) => {
    (d.items || []).forEach(({ item, qty }) => {
      if (!staffFoodConsolidated[item]) staffFoodConsolidated[item] = { total: 0, by: {} };
      staffFoodConsolidated[item].total += Number(qty) || 0;
      staffFoodConsolidated[item].by[d.outlet_id] = (staffFoodConsolidated[item].by[d.outlet_id] || 0) + (Number(qty) || 0);
    });
  });
  const hasStaffFood = Object.keys(staffFoodConsolidated).length > 0;

  if (loading) return <div style={{ textAlign: "center", padding: 40, color: "#999" }}>⏳ Loading...</div>;
  return (
    <div id="print-kitchen">
      {/* Header row: Title + Today/Calendar + Refresh + Print */}
      <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center", marginBottom: 10 }}>
        <div><h3 style={{ fontSize: 15, fontWeight: 700, margin: 0 }}>BK Consolidated</h3><p style={{ fontSize: 11, color: "#888", margin: 0 }}>{pendingOrders.length} pending · {issuedOrders.length} issued · {dispatchedOrders.length} done</p></div>
        <div style={{ display: "flex", gap: 5, alignItems: "center" }}>
          <button onClick={() => setSelDate(today())} style={{ padding: "5px 10px", borderRadius: 6, border: selDate === today() ? "1px solid #BBF7D0" : "1px solid #E0E0DC", background: selDate === today() ? "#F0FDF4" : "#fff", color: selDate === today() ? "#16A34A" : "#777", fontSize: 11, fontWeight: 600, cursor: "pointer", fontFamily: "inherit" }}>Today</button>
          <input type="date" value={selDate} onChange={(e) => setSelDate(e.target.value)} style={{ padding: "4px 6px", borderRadius: 6, border: "1px solid #E0E0DC", fontSize: 11, fontFamily: "inherit", color: "#777", cursor: "pointer", width: 32, background: "#fff" }} />
          <button onClick={load} style={{ padding: "5px 10px", borderRadius: 6, border: "1px solid #E0E0DC", background: "#fff", fontSize: 11, color: "#777", cursor: "pointer" }}>🔄</button>
          <PrintBtn sectionId="print-kitchen" title="BK Challan" />
        </div>
      </div>
      {selDate !== today() && <div style={{ padding: "6px 12px", borderRadius: 6, background: "#FFFBEB", border: "1px solid #FDE68A", fontSize: 11, color: "#92400E", marginBottom: 10, textAlign: "center" }}>Viewing: {selDate}</div>}
      {/* Cycle + Status pills */}
      <div style={{ display: "flex", gap: 5, marginBottom: 10 }}>
        {[{ id: "morning", label: "🌅 Morning", c: "#B45309", bg: "#FFFBEB", border: "#FDE68A" }, { id: "evening", label: "🌇 Evening", c: "#2563EB", bg: "#EFF6FF", border: "#BFDBFE" }, { id: "all", label: "All", c: "#555", bg: "#F5F5F3", border: "#E0E0DC" }].map((c) => (
          <button key={c.id} onClick={() => setCycle(c.id)} style={{ padding: "6px 12px", borderRadius: 6, fontSize: 11, fontWeight: cycle === c.id ? 700 : 500, border: cycle === c.id ? `1px solid ${c.border}` : "1px solid #E0E0DC", cursor: "pointer", fontFamily: "inherit", background: cycle === c.id ? c.bg : "#fff", color: cycle === c.id ? c.c : "#888", whiteSpace: "nowrap" }}>{c.label}</button>
        ))}
        <div style={{ flex: 1 }} />
        <button onClick={() => setShowAll(false)} style={{ padding: "6px 12px", borderRadius: 6, fontSize: 11, fontWeight: !showAll ? 700 : 500, border: !showAll ? "1px solid #FDE68A" : "1px solid #E0E0DC", cursor: "pointer", fontFamily: "inherit", background: !showAll ? "#FFFBEB" : "#fff", color: !showAll ? "#B45309" : "#888", whiteSpace: "nowrap" }}>Pending</button>
        <button onClick={() => setShowAll(true)} style={{ padding: "6px 12px", borderRadius: 6, fontSize: 11, fontWeight: showAll ? 700 : 500, border: showAll ? "1px solid #E0E0DC" : "1px solid #E0E0DC", cursor: "pointer", fontFamily: "inherit", background: showAll ? "#F5F5F3" : "#fff", color: showAll ? "#555" : "#888", whiteSpace: "nowrap" }}>All</button>
      </div>
      {!showAll && pendingOrders.length === 0 && orders.length > 0 && (<div style={{ padding: "10px 14px", borderRadius: 8, background: "#F0FDF4", border: "1px solid #BBF7D0", fontSize: 12, color: "#166534", marginBottom: 12, textAlign: "center" }}>✅ All issued</div>)}

      <div id="print-demand" style={{ background: "#fff", borderRadius: 14, border: "1px solid #E8E8E4", marginBottom: 20 }}>
        <div style={{ padding: "14px 18px", borderBottom: "1px solid #E8E8E4", display: "flex", justifyContent: "space-between", alignItems: "center" }}>
          <span style={{ fontWeight: 700, fontSize: 14 }}>📋 Consolidated Demand</span>
          <div style={{ display: "flex", gap: 6 }}><ExportBtn onClick={() => { const headers = ["Item", "Unit", "TOTAL", ...OUTLETS.map((o) => o.short)]; const rows = BK_ITEMS.filter((bk) => consolidated[bk.id]?.total > 0).map((bk) => { const d = consolidated[bk.id]; return [bk.name, bkDisplayUnit(bk.id, bk.unit) || "", d.total, ...OUTLETS.map((o) => d.by[o.id] || 0)]; }); exportCSV(headers, rows, `demand_${selDate}.csv`); }} /><PrintBtn sectionId="print-demand" title="Consolidated Demand" /></div>
        </div>
        <div style={{ overflowX: "auto" }}><table style={{ width: "100%", borderCollapse: "collapse", fontSize: 12.5 }}><thead><tr style={{ background: "#FAFAF8" }}>{["Item", "TOTAL", ...OUTLETS.map((o) => o.short)].map((h, i) => <th key={i} style={{ ...thS, textAlign: i > 0 ? "center" : "left", color: i === 1 ? "#1A1A1A" : undefined, fontWeight: i === 1 ? 800 : undefined, whiteSpace: "nowrap", minWidth: i === 0 ? 100 : 50, ...(i === 0 ? { position: "sticky", left: 0, background: "#FAFAF8", zIndex: 2 } : {}) }}>{h}</th>)}</tr></thead>
        <tbody>{BK_ITEMS.filter((bk) => consolidated[bk.id]?.total > 0).map((bk) => { const d = consolidated[bk.id]; return (<tr key={bk.id} style={{ borderBottom: "1px solid #F0F0EC" }}><td style={{ ...tdS, fontWeight: 600, position: "sticky", left: 0, background: "#fff", zIndex: 1, whiteSpace: "nowrap" }}>{bk.name} <span style={{ fontSize: 10, color: "#999", fontWeight: 400 }}>{bkDisplayUnit(bk.id, bk.unit)}</span></td><td style={{ ...tdS, textAlign: "center", fontWeight: 800, fontFamily: "'JetBrains Mono', monospace", fontSize: 15, color: "#B45309" }}>{Math.round(d.total * 100) / 100}</td>{OUTLETS.map((o) => { const csItems = closingStocksByOutlet[o.id]; const rawClosing = csItems?.[`cs_${bk.id}`] ?? csItems?.[bk.id]; const closingLabel = rawClosing != null && rawClosing !== "" ? Math.round(Number(rawClosing) * 100) / 100 : "NA"; return (<td key={o.id} style={{ ...tdS, textAlign: "center", color: d.by[o.id] ? "#1A1A1A" : "#DDD" }}>{d.by[o.id] ? Math.round(d.by[o.id] * 100) / 100 : "—"} <span style={{ fontSize: 10, color: "#999", fontWeight: 400 }}>({closingLabel})</span></td>); })}</tr>); })}</tbody></table></div>
      </div>

      {/* Staff Food Requests — separate from the regular demand items above (different
          table, submitted via Manual Entry's "Staff Food" pill), so BK needs its own
          section to actually see what's been asked for. */}
      {hasStaffFood && (
        <div style={{ background: "#fff", borderRadius: 14, border: "1px solid #FDE68A", marginBottom: 20 }}>
          <div style={{ padding: "14px 18px", borderBottom: "1px solid #FDE68A", display: "flex", alignItems: "center", gap: 8 }}>
            <span style={{ fontSize: 18 }}>🍛</span>
            <span style={{ fontWeight: 700, fontSize: 14, color: "#B45309" }}>Staff Food Requests</span>
          </div>
          <div style={{ overflowX: "auto" }}>
            <table style={{ width: "100%", borderCollapse: "collapse", fontSize: 12.5 }}><thead><tr style={{ background: "#FFFBEB" }}>{["Item", "TOTAL", ...OUTLETS.map((o) => o.short)].map((h, i) => <th key={i} style={{ ...thS, textAlign: i > 0 ? "center" : "left", whiteSpace: "nowrap", minWidth: i === 0 ? 100 : 50, ...(i === 0 ? { position: "sticky", left: 0, background: "#FFFBEB", zIndex: 2 } : {}) }}>{h}</th>)}</tr></thead>
              <tbody>{Object.entries(staffFoodConsolidated).map(([itemId, d]) => (
                <tr key={itemId} style={{ borderBottom: "1px solid #F0F0EC" }}>
                  <td style={{ ...tdS, fontWeight: 600, position: "sticky", left: 0, background: "#fff", zIndex: 1, whiteSpace: "nowrap" }}>{staffItemName(itemId)} <span style={{ fontSize: 10, color: "#999", fontWeight: 400 }}>{staffItemUnit(itemId)}</span></td>
                  <td style={{ ...tdS, textAlign: "center", fontWeight: 800, fontFamily: "'JetBrains Mono', monospace", fontSize: 15, color: "#B45309" }}>{Math.round(d.total * 100) / 100}</td>
                  {OUTLETS.map((o) => <td key={o.id} style={{ ...tdS, textAlign: "center", color: d.by[o.id] ? "#1A1A1A" : "#DDD" }}>{d.by[o.id] ? Math.round(d.by[o.id] * 100) / 100 : "—"}</td>)}
                </tr>
              ))}</tbody>
            </table>
          </div>
        </div>
      )}

      {/* Staff Dress Requests — free-form (role + size), so shown as a simple list rather
          than a consolidated quantity table. */}
      {dressDemands.length > 0 && (
        <div style={{ background: "#fff", borderRadius: 14, border: "1px solid #C4B5FD", marginBottom: 20 }}>
          <div style={{ padding: "14px 18px", borderBottom: "1px solid #C4B5FD", display: "flex", alignItems: "center", gap: 8 }}>
            <span style={{ fontSize: 18 }}>👕</span>
            <span style={{ fontWeight: 700, fontSize: 14, color: "#7C3AED" }}>Staff Dress Requests</span>
          </div>
          <div>{dressDemands.flatMap((d) => (d.items || []).map((it, idx) => (
            <div key={`${d.id}_${idx}`} style={{ display: "flex", alignItems: "center", gap: 10, padding: "10px 16px", borderBottom: "1px solid #F0F0EC", fontSize: 13 }}>
              <span style={{ fontWeight: 700, color: "#7C3AED", width: 60 }}>{findOutletForDisplay(d.outlet_id)?.short || d.outlet_id}</span>
              <span style={{ flex: 1 }}>{it.role || "—"} · {it.size || "—"}</span>
              <span style={{ fontSize: 11, color: "#999" }}>{d.submitted_by}</span>
            </div>
          )))}</div>
        </div>
      )}

    </div>
  );
};



// ═════════════════════════════════════════════════════════════════════════════
//  DISPATCH — with per-item qty editing + printable challan
// ═════════════════════════════════════════════════════════════════════════════
// Base Kitchen's own demand (outlet_id "bk") shares this same dispatch queue with the
// 4 real outlets — it isn't in OUTLETS (that array drives per-outlet sales/P&L/closing
// stock breakdowns BK doesn't participate in), so give it a display fallback here instead.
const findOutletForDisplay = (id) => id === "bk" ? { id: "bk", name: "Base Kitchen", short: "🏭 BK" } : OUTLETS.find((o) => o.id === id);

const Dispatch = () => {
  const [orders, setOrders] = useState([]); const [loading, setLoading] = useState(true);
  const [dispatchQty, setDispatchQty] = useState({}); // { orderId: { itemId: qty } }
  const [dispatching, setDispatching] = useState(null);
  const [selOutlet, setSelOutlet] = useState(null);
  const [expandedCat, setExpandedCat] = useState({});
  // Old carried-over challans default folded (just the header) so backlog doesn't bury
  // today's actionable orders — { orderId: true|false }, overriding the default once
  // manually toggled.
  const [orderOpenOverride, setOrderOpenOverride] = useState({});
  const [showOldBacklog, setShowOldBacklog] = useState(false);
  const [challanOrder, setChallanOrder] = useState(null);
  const [challanCat, setChallanCat] = useState(null); // category pill filter on the Dispatch Challan view — null = All
  useEffect(() => { setChallanCat(null); }, [challanOrder]);
  // Staff Food — outlets submit this separately (staff_demands table, no dispatch/receive
  // tracking of its own), so it never showed up on the actual Dispatch Challan a store
  // manager checks off and prints — easy to physically forget when packing. Shown as its
  // own section here (not merged into the regular Demanded/Dispatched table, since staff
  // food has no dispatched-qty concept to compare against) rather than silently omitted.
  const [challanStaffFood, setChallanStaffFood] = useState([]);
  const [challanStaffMasterItems, setChallanStaffMasterItems] = useState([]);
  useEffect(() => {
    if (!challanOrder) { setChallanStaffFood([]); return; }
    Promise.all([
      api.getStaffDemands({ outlet_id: challanOrder.outlet_id, date: challanOrder.date, category: "food" }),
      api.getStaffDemandItems(),
    ]).then(([sd, si]) => { setChallanStaffFood(sd || []); setChallanStaffMasterItems(si || []); })
      .catch(() => { setChallanStaffFood([]); setChallanStaffMasterItems([]); });
  }, [challanOrder]);
  const [checkedItems, setCheckedItems] = useState({}); // { orderId: { itemId: true } } // order to show challan for
  // Items the store manager adds on the phone that weren't in the original written demand
  // (a forgotten item, called in after submission) — merged into the order's item list for
  // display/dispatch, but never written back onto the original demand record itself.
  const [extraItems, setExtraItems] = useState({}); // { orderId: { itemId: qty } }
  const [addingItemTo, setAddingItemTo] = useState(null); // order id currently showing the add-item picker
  const [itemSearch, setItemSearch] = useState("");
  // Which date the "Dispatched" section (below) shows — independent of pending, which is
  // always current backlog regardless of this. Defaults to today; the last-7-days pills
  // plus a calendar input (for anything older) let the store manager look up old challans.
  const [selDate, setSelDate] = useState(today());
  const [olderDispatched, setOlderDispatched] = useState(null);
  const [loadingOlder, setLoadingOlder] = useState(false);
  // Anything still pending (not yet fulfilled) is fetched regardless of date — a demand
  // that slipped through yesterday shouldn't quietly disappear once the date rolls over.
  const load = () => {
    setLoading(true);
    const tomorrow = istDateAgo(-1);
    const windowStart = istDateAgo(13);
    api.getOrders({ from: windowStart }).then((all) => {
      setOrders((all || []).filter((d) => d.date <= tomorrow && (d.date !== tomorrow || d.demand_slot === "morning")));
    }).catch(() => setOrders([])).finally(() => setLoading(false));
  };
  useEffect(load, []);

  // Emergency dispatch — an outlet urgently needs something they never demanded (or a
  // top-up after their slot was already dispatched). Creates a fresh on-behalf order for the
  // selected outlet (backend bypasses the cutoff / already-dispatched guards when
  // emergency:true, owner/store_mgr/bk_manager only), then opens the add-item picker so you
  // add what's going and dispatch it through the normal flow — so it's tracked in stock/P&L,
  // not sent off the books.
  const [creatingEmergency, setCreatingEmergency] = useState(false);
  const createEmergencyDispatch = async () => {
    if (!selOutlet || selOutlet === "bk") { alert("Pick the outlet tab above that you need to emergency-dispatch to first."); return; }
    const outletName = OUTLETS.find((o) => o.id === selOutlet)?.name || selOutlet;
    if (!window.confirm(`🚨 Emergency dispatch for ${outletName}?\n\nThis creates a new on-behalf order (bypassing the normal demand cutoff) that you add items to and dispatch right now. It's flagged as emergency and counts toward ${outletName}'s stock & P&L, same as a normal dispatch.`)) return;
    setCreatingEmergency(true);
    try {
      const istHour = Number(new Date().toLocaleString("en-US", { timeZone: "Asia/Kolkata", hour: "2-digit", hour12: false }));
      const created = await api.createDemand({
        outlet_id: selOutlet, type: "manual", items: {}, status: "submitted",
        demand_slot: istHour < 15 ? "morning" : "evening",
        submitted_by: getCurrentUser()?.name || "Emergency",
        note: "🚨 Emergency dispatch", emergency: true,
      });
      load();
      if (created?.id) { setAddingItemTo(created.id); setItemSearch(""); } // jump straight to adding items
    } catch (e) { alert("Error: " + e.message); }
    finally { setCreatingEmergency(false); }
  };

  // `orders` already covers the last 14 days (see windowStart above), so the 7-day pills
  // are served straight from it with no extra request; only the calendar reaching further
  // back needs a dedicated fetch.
  const withinLoadedWindow = selDate >= istDateAgo(13);
  useEffect(() => {
    if (withinLoadedWindow) { setOlderDispatched(null); return; }
    setLoadingOlder(true);
    api.getOrders({ date: selDate, status: "fulfilled" }).then((d) => setOlderDispatched(d || [])).catch(() => setOlderDispatched([])).finally(() => setLoadingOlder(false));
  }, [selDate, withinLoadedWindow]);

  // Oldest first — a demand that's been sitting unfulfilled since yesterday (or earlier)
  // surfaces above today's, so it isn't missed a second time.
  const pending = orders.filter((o) => (o.status === "submitted" || o.status === "received" || o.status === "issued") && (!selOutlet || o.outlet_id === selOutlet)).sort((a, b) => (a.date || "").localeCompare(b.date || ""));
  // Today's orders render normally; everything carried over from an earlier day is old
  // backlog — grouped under one collapsed summary instead of each taking a full row, so
  // dozens of stale entries don't bury what's actually actionable today.
  const freshPending = pending.filter((o) => o.date === today());
  const oldPending = pending.filter((o) => o.date !== today());
  const done = (withinLoadedWindow ? orders.filter((o) => o.status === "fulfilled" && o.date === selDate) : (olderDispatched || [])).filter((o) => !selOutlet || o.outlet_id === selOutlet);
  const allPending = orders.filter((o) => o.status === "submitted" || o.status === "received" || o.status === "issued");
  const allDone = orders.filter((o) => o.status === "fulfilled" && o.date === today());

  // The order's original demand plus whatever's been phoned in and added here — this is
  // what every item-listing/counting/dispatching codepath below should treat as "the order".
  const orderItems = (order) => ({ ...(order.items || {}), ...(extraItems[order.id] || {}) });
  const isExtraItem = (order, id) => (order.items?.[id] || 0) <= 0 && extraItems[order.id]?.[id] !== undefined;

  const getDispQty = (oid, iid, demandedQty) => {
    if (dispatchQty[oid]?.[iid] !== undefined) return dispatchQty[oid][iid];
    return demandedQty; // default: full qty
  };
  const setDQ = (oid, iid, val) => setDispatchQty((p) => ({ ...p, [oid]: { ...(p[oid] || {}), [iid]: val } }));
  const toggleCat = (key) => setExpandedCat((p) => ({ ...p, [key]: !p[key] }));
  const isChecked = (oid, iid) => !!checkedItems[oid]?.[iid];
  const toggleCheck = (oid, iid) => setCheckedItems((p) => ({ ...p, [oid]: { ...(p[oid] || {}), [iid]: !p[oid]?.[iid] } }));
  const checkAllCat = (oid, catItems) => {
    const allChecked = catItems.every(([id]) => isChecked(oid, id));
    setCheckedItems((p) => {
      const oCopy = { ...(p[oid] || {}) };
      catItems.forEach(([id]) => { oCopy[id] = !allChecked; });
      return { ...p, [oid]: oCopy };
    });
  };
  const getCheckedCount = (oid, itemEntries) => itemEntries.filter(([id]) => isChecked(oid, id)).length;

  // Adds a phoned-in item to this order — merged into its item list, category expanded so
  // it's immediately visible. Left unchecked with an editable qty, same as every other
  // item here: the store manager types the real qty they were told, then ticks it like any
  // other line, rather than trusting a guessed default.
  const addExtraItem = (order, itemId) => {
    setExtraItems((p) => ({ ...p, [order.id]: { ...(p[order.id] || {}), [itemId]: 1 } }));
    const sec = DEMAND_SECTIONS.find((s) => s.items.some((i) => i.id === itemId));
    if (sec) setExpandedCat((p) => ({ ...p, [`${order.id}_${sec.id}`]: true }));
    setAddingItemTo(null); setItemSearch("");
  };
  const removeExtraItem = (order, itemId) => {
    setExtraItems((p) => { const c = { ...(p[order.id] || {}) }; delete c[itemId]; return { ...p, [order.id]: c }; });
    setCheckedItems((p) => { const c = { ...(p[order.id] || {}) }; delete c[itemId]; return { ...p, [order.id]: c }; });
  };
  const [cancelling, setCancelling] = useState(null); // order id, or `${orderId}_${itemId}` while a cancel is in flight

  // Store decided it's not sending this one item — written off the actual demand record
  // (not just skipped for today), so it stops resurfacing as "carried over" tomorrow. A
  // phoned-in item that was never saved just gets dropped locally, no API call needed.
  const cancelItem = async (order, itemId) => {
    if (isExtraItem(order, itemId)) { removeExtraItem(order, itemId); return; }
    if (!confirm(`Remove ${getItemName(itemId)} from this demand? The outlet will need to re-order it if they still need it.`)) return;
    setCancelling(`${order.id}_${itemId}`);
    try {
      const remaining = { ...(order.items || {}) };
      delete remaining[itemId];
      if (Object.keys(remaining).length === 0) await api.cancelDemand(order.id, "last item removed");
      else await api.updateDemand(order.id, { items: remaining });
      load();
    } catch (e) { alert("Error: " + e.message); }
    finally { setCancelling(null); }
  };

  // Whole order written off — the store has decided none of it is going out.
  const cancelOrder = async (order) => {
    if (!confirm(`Cancel this entire demand from ${findOutletForDisplay(order.outlet_id)?.name || order.outlet_id}? Nothing will be marked as dispatched.`)) return;
    setCancelling(order.id);
    try {
      await api.cancelDemand(order.id);
      load();
    } catch (e) { alert("Error: " + e.message); }
    finally { setCancelling(null); }
  };

  const doDispatch = async (order) => {
    const itemEntries = Object.entries(orderItems(order)).filter(([, q]) => q > 0);
    // Only dispatch CHECKED items
    const dispItems = {};
    const remainingItems = {};
    let hasAny = false;
    itemEntries.forEach(([id, demandedQty]) => {
      if (isChecked(order.id, id)) {
        const actualQty = Number(getDispQty(order.id, id, demandedQty)) || 0;
        if (actualQty > 0) { dispItems[id] = actualQty; hasAny = true; }
      } else {
        // Unchecked items stay as remaining
        remainingItems[id] = demandedQty;
      }
    });
    if (!hasAny) { alert("Tick at least 1 item to dispatch"); return; }
    // A phoned-in item (added via "+ Add Item" below, never touched the outlet manager's
    // UnitPicker) never got an items_units tag — stamp Kg for the 3 standardized batter
    // items here so they don't silently fall back to the catalog default ("Batch")
    // downstream. Everything else keeps whatever unit the original demand already used.
    const newItemsUnits = {};
    Object.keys(dispItems).forEach((id) => { if (isExtraItem(order, id) && KG_STANDARDIZED_ITEMS.has(id)) newItemsUnits[id] = "Kg"; });
    setDispatching(order.id);
    try {
      await api.dispatchOrder(order.id, dispItems, getCurrentUser()?.name || "store", remainingItems, newItemsUnits);
      setCheckedItems((p) => { const c = { ...p }; delete c[order.id]; return c; });
      setDispatchQty((p) => { const c = { ...p }; delete c[order.id]; return c; });
      setExtraItems((p) => { const c = { ...p }; delete c[order.id]; return c; });
      load();
    } catch (e) { alert("Error: " + e.message); }
    finally { setDispatching(null); }
  };

  // Group items by category from DEMAND_SECTIONS
  const getItemsByCategory = (items) => {
    const grouped = {};
    DEMAND_SECTIONS.forEach((sec) => { grouped[sec.id] = { label: sec.titleHi, emoji: sec.emoji, color: sec.color, bg: sec.bg, border: sec.border, items: [] }; });
    grouped["_other"] = { label: "Other", emoji: "📦", color: "#666", bg: "#FAFAF8", border: "#E0E0DC", items: [] };
    Object.entries(items).filter(([, q]) => q > 0).forEach(([id, qty]) => {
      let found = false;
      DEMAND_SECTIONS.forEach((sec) => { if (sec.items.some((i) => i.id === id)) { grouped[sec.id].items.push([id, qty]); found = true; } });
      if (!found) grouped["_other"].items.push([id, qty]);
    });
    return Object.entries(grouped).filter(([, g]) => g.items.length > 0);
  };

  // Get item name from any section
  const getItemName = (id) => {
    for (const sec of DEMAND_SECTIONS) { const it = sec.items.find((i) => i.id === id); if (it) return it.name; }
    const bk = BK_ITEMS.find((b) => b.id === id); if (bk) return bk.name;
    return id;
  };
  const getItemUnit = (id) => {
    for (const sec of DEMAND_SECTIONS) { const it = sec.items.find((i) => i.id === id); if (it) return bkDisplayUnit(id, it.unit); }
    return "";
  };

  // ── CHALLAN VIEW ──
  if (challanOrder) {
    const order = challanOrder;
    const outlet = findOutletForDisplay(order.outlet_id);
    const demanded = order.items || {};
    const dispatched = order.dispatch_items || demanded; // fallback for old orders without dispatch_items
    const allIds = [...new Set([...Object.keys(demanded), ...Object.keys(dispatched)])].filter((id) => (demanded[id] || 0) > 0 || (dispatched[id] || 0) > 0);
    // Category pills at the top of the challan — lets the store/outlet manager check off
    // just one section (e.g. only Vegetables) instead of scrolling the full flat list.
    // Grouped straight off allIds (not just demanded) so an extra dispatched-only item
    // still lands under its real category instead of silently falling out of every pill.
    const challanCatGroups = (() => {
      const groups = {};
      allIds.forEach((id) => {
        const sec = DEMAND_SECTIONS.find((s) => s.items.some((i) => i.id === id));
        const catId = sec?.id || "_other";
        if (!groups[catId]) groups[catId] = { id: catId, titleHi: sec?.titleHi || "Other", emoji: sec?.emoji || "📦", ids: [] };
        groups[catId].ids.push(id);
      });
      return Object.values(groups);
    })();
    const visibleIds = challanCat ? (challanCatGroups.find((g) => g.id === challanCat)?.ids || []) : allIds;
    const dateStr = order.date || today();
    const timeStr = order.dispatched_at ? new Date(order.dispatched_at).toLocaleTimeString("en-IN", { hour: "2-digit", minute: "2-digit", timeZone: "Asia/Kolkata" }) : new Date(order.submitted_at).toLocaleTimeString("en-IN", { hour: "2-digit", minute: "2-digit", timeZone: "Asia/Kolkata" });

    // Staff Food requested for this same outlet+date — matched by shift when the order
    // has one (a morning demand's challan shouldn't pull in an evening-only staff food
    // request), otherwise folds every shift together.
    // staff_demands.shift uses 'am'/'pm', demands.demand_slot uses 'morning'/'evening' —
    // different vocabularies for the same morning/evening concept, so map before comparing.
    const orderShift = order.demand_slot === "morning" ? "am" : order.demand_slot === "evening" ? "pm" : null;
    const staffFoodForOrder = challanStaffFood.filter((d) => !orderShift || d.shift === orderShift);
    const staffFoodConsolidated = {}; // item_id -> qty
    staffFoodForOrder.forEach((d) => (d.items || []).forEach(({ item, qty }) => {
      staffFoodConsolidated[item] = (staffFoodConsolidated[item] || 0) + (Number(qty) || 0);
    }));
    const staffFoodName = (id) => challanStaffMasterItems.find((i) => i.id === id)?.name || id;
    const staffFoodUnit = (id) => challanStaffMasterItems.find((i) => i.id === id)?.unit || "";
    const staffFoodRows = Object.entries(staffFoodConsolidated).filter(([, qty]) => qty > 0);

    const printChallan = () => {
      const pw = window.open("", "_blank");
      const rows = allIds.map((id) => {
        const dem = demanded[id] || 0;
        const disp = dispatched[id] || 0;
        const short = disp < dem;
        return `<tr style="${short ? "background:#FEF2F2" : ""}"><td style="padding:8px 10px;border-bottom:1px solid #E8E8E4;font-weight:600">${getItemName(id)}</td><td style="padding:8px 10px;border-bottom:1px solid #E8E8E4;text-align:center;color:#999;font-size:11px">${getItemUnit(id)}</td><td style="padding:8px 10px;border-bottom:1px solid #E8E8E4;text-align:center;font-family:monospace">${dem}</td><td style="padding:8px 10px;border-bottom:1px solid #E8E8E4;text-align:center;font-weight:700;font-family:monospace;color:${short ? "#DC2626" : "#16A34A"}">${disp}</td><td style="padding:8px 10px;border-bottom:1px solid #E8E8E4;text-align:center;font-size:11px;color:${short ? "#DC2626" : "#16A34A"}">${short ? "⬇ " + (dem - disp) + " short" : disp === dem ? "✓" : "⬆ +" + (disp - dem)}</td></tr>`;
      }).join("");
      const staffFoodHtml = staffFoodRows.length === 0 ? "" : `<div style="margin-top:20px"><h2 style="font-size:13px;font-weight:800;color:#B45309;border-bottom:2px solid #FDE68A;padding-bottom:6px;margin-bottom:8px">🍛 Staff Food</h2><table style="width:100%;border-collapse:collapse;font-size:13px"><thead><tr style="background:#FFFBEB"><th style="padding:8px 10px;text-align:left;font-size:10px;font-weight:700;color:#92400E;text-transform:uppercase;border-bottom:2px solid #FDE68A">Item</th><th style="padding:8px 10px;text-align:center;font-size:10px;font-weight:700;color:#92400E;text-transform:uppercase;border-bottom:2px solid #FDE68A">Unit</th><th style="padding:8px 10px;text-align:center;font-size:10px;font-weight:700;color:#92400E;text-transform:uppercase;border-bottom:2px solid #FDE68A">Qty</th></tr></thead><tbody>${staffFoodRows.map(([id, qty]) => `<tr><td style="padding:8px 10px;border-bottom:1px solid #F0F0EC;font-weight:600">${staffFoodName(id)}</td><td style="padding:8px 10px;border-bottom:1px solid #F0F0EC;text-align:center;color:#999;font-size:11px">${staffFoodUnit(id)}</td><td style="padding:8px 10px;border-bottom:1px solid #F0F0EC;text-align:center;font-weight:700;font-family:monospace">${qty}</td></tr>`).join("")}</tbody></table></div>`;
      pw.document.write(`<!DOCTYPE html><html><head><title>Dispatch Challan</title><link href="https://fonts.googleapis.com/css2?family=Outfit:wght@400;600;700;800&family=JetBrains+Mono:wght@400;600;700&display=swap" rel="stylesheet"><style>*{box-sizing:border-box;margin:0;padding:0}body{font-family:'Outfit',sans-serif;color:#1A1A1A;padding:24px}@media print{body{padding:12px}}</style></head><body><div style="display:flex;justify-content:space-between;align-items:flex-start;border-bottom:2px solid #1A1A1A;padding-bottom:12px;margin-bottom:16px"><div><h1 style="font-size:18px;font-weight:800">The The Ananda Cafe — Dispatch Challan</h1><p style="font-size:12px;color:#888;margin-top:2px">🏪 ${outlet?.name || order.outlet_id}</p></div><div style="text-align:right"><div style="font-size:12px;color:#888">${dateStr}</div><div style="font-size:11px;color:#BBB">${timeStr}</div></div></div><table style="width:100%;border-collapse:collapse;font-size:13px"><thead><tr style="background:#F8F8F5"><th style="padding:8px 10px;text-align:left;font-size:10px;font-weight:700;color:#666;text-transform:uppercase;border-bottom:2px solid #DDD">Item</th><th style="padding:8px 10px;text-align:center;font-size:10px;font-weight:700;color:#666;text-transform:uppercase;border-bottom:2px solid #DDD">Unit</th><th style="padding:8px 10px;text-align:center;font-size:10px;font-weight:700;color:#666;text-transform:uppercase;border-bottom:2px solid #DDD">Demanded</th><th style="padding:8px 10px;text-align:center;font-size:10px;font-weight:700;color:#666;text-transform:uppercase;border-bottom:2px solid #DDD">Dispatched</th><th style="padding:8px 10px;text-align:center;font-size:10px;font-weight:700;color:#666;text-transform:uppercase;border-bottom:2px solid #DDD">Status</th></tr></thead><tbody>${rows}</tbody></table>${staffFoodHtml}<div style="margin-top:20px;display:flex;justify-content:space-between;font-size:11px;color:#999"><span>Total: ${allIds.length} items${staffFoodRows.length > 0 ? ` + ${staffFoodRows.length} staff food` : ""}</span><span>Generated: ${new Date().toLocaleString("en-IN", { timeZone: "Asia/Kolkata" })}</span></div><div style="margin-top:40px;display:flex;justify-content:space-between"><div style="text-align:center"><div style="border-top:1px solid #999;width:120px;margin-top:40px;padding-top:4px;font-size:10px;color:#888">Store Manager</div></div><div style="text-align:center"><div style="border-top:1px solid #999;width:120px;margin-top:40px;padding-top:4px;font-size:10px;color:#888">Transport</div></div><div style="text-align:center"><div style="border-top:1px solid #999;width:120px;margin-top:40px;padding-top:4px;font-size:10px;color:#888">Outlet Manager</div></div></div></body></html>`);
      pw.document.close();
      setTimeout(() => { pw.focus(); pw.print(); }, 400);
    };

    return (
      <div>
        <div style={{ display: "flex", alignItems: "center", gap: 10, marginBottom: 16 }}>
          <BackBtn onClick={() => setChallanOrder(null)} />
          <div style={{ flex: 1 }}>
            <div style={{ fontSize: 15, fontWeight: 800 }}>📋 Dispatch Challan</div>
            <div style={{ fontSize: 11, color: "#999" }}>{outlet?.name} — {dateStr}</div>
          </div>
          <button onClick={printChallan} style={{ padding: "6px 14px", borderRadius: 8, border: "1px solid #E0E0DC", background: "#fff", fontSize: 12, fontWeight: 600, color: "#777", cursor: "pointer", fontFamily: "inherit" }}>🖨️ Print</button>
        </div>

        {/* Category pills — filter the table to one section at a time (Print always
            includes everything, regardless of this filter). */}
        <div style={{ display: "flex", gap: 6, marginBottom: 12, overflowX: "auto", paddingBottom: 4, flexWrap: "wrap" }}>
          <button onClick={() => setChallanCat(null)} style={{ padding: "6px 12px", borderRadius: 8, fontSize: 11, fontWeight: !challanCat ? 700 : 500, border: !challanCat ? "none" : "1px solid #E0E0DC", cursor: "pointer", fontFamily: "inherit", background: !challanCat ? "#1A1A1A" : "#fff", color: !challanCat ? "#fff" : "#888", whiteSpace: "nowrap" }}>All ({allIds.length})</button>
          {challanCatGroups.map((g) => (
            <button key={g.id} onClick={() => setChallanCat(challanCat === g.id ? null : g.id)} style={{ padding: "6px 12px", borderRadius: 8, fontSize: 11, fontWeight: challanCat === g.id ? 700 : 500, border: challanCat === g.id ? "none" : "1px solid #E0E0DC", cursor: "pointer", fontFamily: "inherit", background: challanCat === g.id ? "#1A1A1A" : "#fff", color: challanCat === g.id ? "#fff" : "#888", whiteSpace: "nowrap" }}>{g.emoji} {g.titleHi} ({g.ids.length})</button>
          ))}
        </div>

        <div style={{ background: "#fff", borderRadius: 14, border: "1px solid #E8E8E4", overflow: "hidden" }}>
          <div style={{ overflowX: "auto" }}>
            <table style={{ width: "100%", borderCollapse: "collapse", fontSize: 13 }}>
              <thead><tr style={{ background: "#FAFAF8" }}>
                <th style={thS}>Item</th>
                <th style={{ ...thS, textAlign: "center" }}>Unit</th>
                <th style={{ ...thS, textAlign: "center" }}>Demanded</th>
                <th style={{ ...thS, textAlign: "center" }}>Dispatched</th>
                <th style={{ ...thS, textAlign: "center" }}>Status</th>
              </tr></thead>
              <tbody>
                {visibleIds.map((id) => {
                  const dem = demanded[id] || 0;
                  const disp = dispatched[id] || 0;
                  const isShort = disp < dem;
                  const isOver = disp > dem;
                  return (
                    <tr key={id} style={{ borderBottom: "1px solid #F0F0EC", background: isShort ? "#FEF2F2" : "transparent" }}>
                      <td style={{ ...tdS, fontWeight: 600 }}>{getItemName(id)}</td>
                      <td style={{ ...tdS, textAlign: "center", color: "#999", fontSize: 11 }}>{getItemUnit(id)}</td>
                      <td style={{ ...tdS, textAlign: "center", fontFamily: "'JetBrains Mono', monospace" }}>{dem}</td>
                      <td style={{ ...tdS, textAlign: "center", fontWeight: 700, fontFamily: "'JetBrains Mono', monospace", color: isShort ? "#DC2626" : "#16A34A" }}>{disp}</td>
                      <td style={{ ...tdS, textAlign: "center" }}>
                        <span style={{ padding: "2px 8px", borderRadius: 5, fontSize: 10, fontWeight: 700, background: isShort ? "#FEF2F2" : "#F0FDF4", color: isShort ? "#DC2626" : "#16A34A" }}>
                          {isShort ? `⬇ ${dem - disp} short` : isOver ? `⬆ +${disp - dem}` : "✓ Full"}
                        </span>
                      </td>
                    </tr>
                  );
                })}
              </tbody>
            </table>
          </div>
        </div>

        {staffFoodRows.length > 0 && (
          <div style={{ background: "#fff", borderRadius: 14, border: "1px solid #FDE68A", overflow: "hidden", marginTop: 14 }}>
            <div style={{ padding: "10px 14px", borderBottom: "1px solid #FDE68A", background: "#FFFBEB", display: "flex", alignItems: "center", gap: 8 }}>
              <span style={{ fontSize: 16 }}>🍛</span>
              <span style={{ fontWeight: 700, fontSize: 13, color: "#B45309" }}>Staff Food</span>
            </div>
            <div style={{ overflowX: "auto" }}>
              <table style={{ width: "100%", borderCollapse: "collapse", fontSize: 13 }}>
                <thead><tr style={{ background: "#FFFBEB" }}>
                  <th style={thS}>Item</th>
                  <th style={{ ...thS, textAlign: "center" }}>Unit</th>
                  <th style={{ ...thS, textAlign: "center" }}>Qty</th>
                </tr></thead>
                <tbody>
                  {staffFoodRows.map(([id, qty]) => (
                    <tr key={id} style={{ borderBottom: "1px solid #F0F0EC" }}>
                      <td style={{ ...tdS, fontWeight: 600 }}>{staffFoodName(id)}</td>
                      <td style={{ ...tdS, textAlign: "center", color: "#999", fontSize: 11 }}>{staffFoodUnit(id)}</td>
                      <td style={{ ...tdS, textAlign: "center", fontWeight: 700, fontFamily: "'JetBrains Mono', monospace" }}>{qty}</td>
                    </tr>
                  ))}
                </tbody>
              </table>
            </div>
          </div>
        )}
      </div>
    );
  }

  if (loading) return <div style={{ textAlign: "center", padding: 40, color: "#999" }}>⏳ Loading...</div>;

  const outletCounts = {};
  OUTLETS.forEach((o) => { outletCounts[o.id] = allPending.filter((d) => d.outlet_id === o.id).length; });

  return (
    <div>
      {/* Outlet pills + refresh */}
      <div style={{ display: "flex", gap: 5, marginBottom: 12, overflowX: "auto", paddingBottom: 4, alignItems: "center" }}>
        {[{ id: "bk", short: "🏭 BK" }, ...OUTLETS].map((o) => {
          const pCount = allPending.filter((d) => d.outlet_id === o.id).length;
          const dCount = allDone.filter((d) => d.outlet_id === o.id).length;
          const isAllDone = pCount === 0 && dCount > 0;
          return (<button key={o.id} onClick={() => setSelOutlet(selOutlet === o.id ? null : o.id)} style={{ padding: "6px 12px", borderRadius: 8, fontSize: 11, fontWeight: selOutlet === o.id ? 700 : 500, border: selOutlet === o.id ? "1px solid #FDE68A" : isAllDone ? "1px solid #BBF7D0" : "1px solid #E0E0DC", cursor: "pointer", fontFamily: "inherit", background: selOutlet === o.id ? "#FFFBEB" : isAllDone ? "#F0FDF4" : "#fff", color: selOutlet === o.id ? "#B45309" : "#888", display: "flex", alignItems: "center", gap: 4, whiteSpace: "nowrap", flexShrink: 0 }}>
            {isAllDone && <span style={{ fontSize: 9 }}>✅</span>}
            {pCount > 0 && <span style={{ width: 6, height: 6, borderRadius: 3, background: "#F59E0B", flexShrink: 0 }} />}
            {o.short}
          </button>);
        })}
        <div style={{ flex: 1 }} />
        <button onClick={createEmergencyDispatch} disabled={creatingEmergency} title="Emergency: create an on-behalf dispatch order for the selected outlet (bypasses the normal cutoff)" style={{ padding: "5px 12px", borderRadius: 6, border: "1px solid #FECACA", background: "#FEF2F2", fontSize: 11, fontWeight: 700, color: "#DC2626", cursor: creatingEmergency ? "not-allowed" : "pointer", flexShrink: 0, fontFamily: "inherit" }}>{creatingEmergency ? "…" : "🚨 Emergency"}</button>
        <button onClick={load} style={{ padding: "5px 10px", borderRadius: 6, border: "1px solid #E0E0DC", background: "#fff", fontSize: 11, color: "#777", cursor: "pointer", flexShrink: 0 }}>🔄</button>
      </div>

      {pending.length === 0 && <div style={{ background: "#fff", borderRadius: 14, border: "1px solid #E8E8E4", padding: "40px 20px", textAlign: "center" }}><div style={{ fontSize: 36, marginBottom: 8 }}>✓</div><div style={{ color: "#999", marginBottom: selOutlet && selOutlet !== "bk" ? 16 : 0 }}>{selOutlet ? `No pending for ${OUTLETS.find((o) => o.id === selOutlet)?.name}` : "All dispatched for today"}</div>{selOutlet && selOutlet !== "bk" && <button onClick={createEmergencyDispatch} disabled={creatingEmergency} style={{ padding: "10px 18px", borderRadius: 10, border: "1px solid #FECACA", background: "#FEF2F2", fontSize: 13, fontWeight: 700, color: "#DC2626", cursor: creatingEmergency ? "not-allowed" : "pointer", fontFamily: "inherit" }}>{creatingEmergency ? "Creating…" : `🚨 Emergency Dispatch to ${OUTLETS.find((o) => o.id === selOutlet)?.short || ""}`}</button>}</div>}

      {/* ── PENDING ORDERS ── */}
      {(() => { const renderOrderCard = (order) => {
        const outlet = findOutletForDisplay(order.outlet_id);
        const mergedItems = orderItems(order);
        const itemEntries = Object.entries(mergedItems).filter(([, q]) => q > 0);
        const hasItems = itemEntries.length > 0;
        const categories = hasItems ? getItemsByCategory(mergedItems) : [];
        const filledCount = hasItems ? itemEntries.filter(([id, q]) => Number(getDispQty(order.id, id, q)) > 0).length : 0;
        const hasShortage = hasItems && itemEntries.some(([id, q]) => Number(getDispQty(order.id, id, q)) < q);
        const checkedCount = hasItems ? getCheckedCount(order.id, itemEntries) : 0;
        const allChecked = hasItems && checkedCount === itemEntries.length;
        const isCarriedOver = order.date !== today();
        const orderOpen = orderOpenOverride[order.id] !== undefined ? orderOpenOverride[order.id] : !isCarriedOver;
        const isAddingItem = addingItemTo === order.id;
        const itemSearchResults = isAddingItem && itemSearch.trim()
          ? DEMAND_SECTIONS.flatMap((sec) => sec.items.map((i) => ({ ...i, sectionId: sec.id }))).filter((i) => i.name.toLowerCase().includes(itemSearch.trim().toLowerCase()) && !(mergedItems[i.id] > 0)).slice(0, 8)
          : [];

        return (
          <div key={order.id} style={{ marginBottom: 10 }}>
          <div style={{ background: "#fff", borderRadius: 12, border: isCarriedOver ? "1px solid #FDE68A" : "1px solid #E8E8E4", overflow: "hidden" }}>
            {/* Header — old carried-over challans fold to just this line by default */}
            <div onClick={() => isCarriedOver && setOrderOpenOverride((p) => ({ ...p, [order.id]: !orderOpen }))} style={{ padding: "10px 14px", display: "flex", justifyContent: "space-between", alignItems: "center", borderBottom: orderOpen ? "1px solid #F0F0EC" : "none", cursor: isCarriedOver ? "pointer" : "default" }}>
              <div style={{ display: "flex", alignItems: "center", gap: 6 }}>
                <span style={{ fontSize: 12, fontWeight: 700 }}>{outlet?.short || order.outlet_id}</span>
                <span style={{ fontSize: 10, color: "#999" }}>{order.type === "photo" ? "📷" : "✏️"}</span>
                <span style={{ fontSize: 10, color: "#BBB" }}>{new Date(order.submitted_at).toLocaleTimeString("en-IN", { hour: "2-digit", minute: "2-digit", timeZone: "Asia/Kolkata" })}</span>
              </div>
              <div style={{ display: "flex", alignItems: "center", gap: 6 }}>
                {isCarriedOver && <span style={{ fontSize: 9, padding: "1px 6px", borderRadius: 3, background: "#FFFBEB", color: "#B45309", fontWeight: 700 }}>⚠️ Since {order.date} {orderOpen ? "▲" : "▼"}</span>}
                {hasShortage && <span style={{ fontSize: 9, padding: "1px 6px", borderRadius: 3, background: "#FFFBEB", color: "#B45309", fontWeight: 700 }}>Partial</span>}
                {hasItems && <span style={{ fontSize: 11, fontWeight: 700, color: allChecked ? "#16A34A" : "#B45309" }}>✓{checkedCount}/{itemEntries.length}</span>}
                <button onClick={(e) => { e.stopPropagation(); cancelOrder(order); }} disabled={cancelling === order.id} title="Not sending any of this — cancel the whole demand" style={{ padding: "2px 6px", borderRadius: 4, border: "1px solid #FECACA", background: "#fff", color: "#DC2626", fontSize: 10, fontWeight: 700, cursor: "pointer", fontFamily: "inherit" }}>{cancelling === order.id ? "⏳" : "✕"}</button>
              </div>
            </div>

            {orderOpen && <>
            {order.note && <div style={{ padding: "8px 18px", fontSize: 12, color: "#888", borderBottom: "1px solid #F0F0EC" }}>📝 {order.note}</div>}

            {/* Category-wise items with qty editing + verification checkboxes */}
            {hasItems ? categories.map(([catId, cat]) => {
              const catKey = `${order.id}_${catId}`;
              const isOpen = expandedCat[catKey] !== false;
              const catChecked = cat.items.filter(([id]) => isChecked(order.id, id)).length;
              const catTotal = cat.items.length;
              return (
                <div key={catKey}>
                  <div onClick={() => toggleCat(catKey)} style={{ padding: "10px 18px", display: "flex", alignItems: "center", gap: 8, cursor: "pointer", background: cat.bg, borderBottom: "1px solid #F0F0EC" }}>
                    <span style={{ fontSize: 16 }}>{cat.emoji}</span>
                    <span style={{ flex: 1, fontSize: 13, fontWeight: 700, color: cat.color }}>{cat.label}</span>
                    <span style={{ fontSize: 11, fontWeight: 700, color: catChecked === catTotal ? "#16A34A" : "#999" }}>{catChecked}/{catTotal}</span>
                    <button onClick={(e) => { e.stopPropagation(); checkAllCat(order.id, cat.items); }} style={{ padding: "2px 8px", borderRadius: 4, border: "1px solid #E0E0DC", background: "#fff", fontSize: 10, fontWeight: 600, color: "#888", cursor: "pointer", fontFamily: "inherit" }}>{catChecked === catTotal ? "✕" : "✓ All"}</button>
                    <span style={{ color: "#CCC", transform: isOpen ? "rotate(180deg)" : "", transition: "0.2s", fontSize: 12 }}>▾</span>
                  </div>
                  {isOpen && <div style={{ padding: "4px 14px 8px" }}>
                    {/* Column headers */}
                    <div style={{ display: "flex", alignItems: "center", gap: 8, padding: "4px 8px", marginBottom: 4 }}>
                      <span style={{ width: 24 }} />
                      <span style={{ width: 210, fontSize: 9, fontWeight: 700, color: "#BBB", textTransform: "uppercase", letterSpacing: 0.5 }}>Item</span>
                      <span style={{ width: 50, textAlign: "center", fontSize: 9, fontWeight: 700, color: "#BBB", textTransform: "uppercase" }}>Asked</span>
                      <span style={{ width: 56, textAlign: "center", fontSize: 9, fontWeight: 700, color: "#BBB", textTransform: "uppercase" }}>Send</span>
                      <span style={{ flex: 1 }} />
                    </div>
                    {cat.items.map(([id, qty]) => {
                      const dispVal = getDispQty(order.id, id, qty);
                      const isShort = Number(dispVal) < qty;
                      const isZero = Number(dispVal) === 0;
                      const checked = isChecked(order.id, id);
                      const isExtra = isExtraItem(order, id);
                      return (
                        <div key={id} style={{ display: "flex", alignItems: "center", gap: 8, padding: "8px 8px", borderRadius: 10, marginBottom: 2, background: isExtra ? "#EFF6FF" : checked ? "#F0FDF4" : isZero ? "#FEF2F2" : isShort ? "#FFFBEB" : "transparent", opacity: checked ? 0.7 : 1 }}>
                          <button onClick={() => toggleCheck(order.id, id)} style={{ width: 24, height: 24, borderRadius: 6, border: checked ? "2px solid #16A34A" : "2px solid #D0D0CC", background: checked ? "#16A34A" : "#fff", display: "flex", alignItems: "center", justifyContent: "center", cursor: "pointer", flexShrink: 0, padding: 0 }}>
                            {checked && <span style={{ color: "#fff", fontSize: 13, fontWeight: 800 }}>✓</span>}
                          </button>
                          <span title={getItemName(id)} style={{ width: 210, flexShrink: 0, overflow: "hidden", textOverflow: "ellipsis", whiteSpace: "nowrap", fontSize: 13, fontWeight: 600, color: isZero ? "#DC2626" : "#1A1A1A", textDecoration: checked ? "line-through" : "none" }}>
                            {getItemName(id)}
                            {isExtra && <span style={{ marginLeft: 6, padding: "1px 6px", borderRadius: 3, fontSize: 8, fontWeight: 700, background: "#2563EB", color: "#fff" }}>➕ PHONED IN</span>}
                          </span>
                          {isExtra ? (
                            <input type="number" inputMode="numeric" min="0" value={qty}
                              onChange={(e) => { const v = Math.max(0, Number(e.target.value) || 0); setExtraItems((p) => ({ ...p, [order.id]: { ...(p[order.id] || {}), [id]: v } })); }}
                              style={{ width: 50, padding: "5px 4px", borderRadius: 6, border: "1px solid #BFDBFE", fontSize: 14, textAlign: "center", fontFamily: "'JetBrains Mono', monospace", fontWeight: 700, color: "#2563EB", background: "#fff" }} />
                          ) : (
                            <span style={{ width: 50, textAlign: "center", fontSize: 14, fontWeight: 700, fontFamily: "'JetBrains Mono', monospace", color: "#888" }}>{qty}</span>
                          )}
                          <input type="number" inputMode="numeric" min="0" value={dispVal}
                            onChange={(e) => setDQ(order.id, id, Math.max(0, Number(e.target.value) || 0))}
                            disabled={checked}
                            style={{ width: 56, padding: "5px 4px", borderRadius: 6, border: isShort ? "2px solid #F59E0B" : isZero ? "2px solid #DC2626" : "1px solid #E0E0DC", fontSize: 14, textAlign: "center", fontFamily: "'JetBrains Mono', monospace", fontWeight: 700, color: isZero ? "#DC2626" : isShort ? "#B45309" : "#16A34A", background: checked ? "#F0FDF4" : "#fff" }} />
                          <span style={{ fontSize: 10, color: "#999", width: 28 }}>{getItemUnit(id)}</span>
                          <span style={{ flex: 1 }} />
                          <button onClick={() => cancelItem(order, id)} disabled={cancelling === `${order.id}_${id}`} title={isExtra ? "Remove" : "Not sending this — cancel it"} style={{ padding: "2px 4px", border: "none", background: "transparent", color: "#DC2626", fontSize: 13, cursor: "pointer", flexShrink: 0 }}>{isExtra ? "🗑️" : "✕"}</button>
                        </div>
                      );
                    })}
                  </div>}
                </div>
              );
            }) : (order.note && String(order.note).includes("Emergency")) ? <div style={{ padding: "14px 18px", fontSize: 12, color: "#B45309", fontWeight: 600 }}>🚨 Emergency order — add what you're sending with "+ Add Item" below, then dispatch.</div> : <div style={{ padding: "14px 18px", fontSize: 12, color: "#888" }}>📷 Photo order — verify manually.</div>}

            {/* Phoned-in item, forgotten at demand time — add it straight into this dispatch */}
            <div style={{ padding: "8px 18px 12px", borderTop: hasItems ? "1px solid #F0F0EC" : "none" }}>
              {!isAddingItem ? (
                <button onClick={() => { setAddingItemTo(order.id); setItemSearch(""); }} style={{ padding: "6px 12px", borderRadius: 8, border: "1px dashed #BFDBFE", background: "#EFF6FF", fontSize: 11, fontWeight: 700, color: "#2563EB", cursor: "pointer", fontFamily: "inherit" }}>📞 + Add Item (phoned in)</button>
              ) : (
                <div style={{ position: "relative" }}>
                  <input autoFocus value={itemSearch} onChange={(e) => setItemSearch(e.target.value)} placeholder="Search item to add..."
                    style={{ width: "100%", padding: "8px 12px", borderRadius: 8, border: "1px solid #BFDBFE", fontSize: 12, fontFamily: "inherit", boxSizing: "border-box" }} />
                  <button onClick={() => { setAddingItemTo(null); setItemSearch(""); }} style={{ position: "absolute", right: 6, top: 6, padding: "2px 6px", border: "none", background: "transparent", color: "#999", fontSize: 12, cursor: "pointer" }}>✕</button>
                  {itemSearch.trim() && (
                    <div style={{ marginTop: 4, background: "#fff", border: "1px solid #E0E0DC", borderRadius: 8, overflow: "hidden", maxHeight: 180, overflowY: "auto" }}>
                      {itemSearchResults.length === 0 && <div style={{ padding: "10px 12px", fontSize: 12, color: "#999" }}>No match</div>}
                      {itemSearchResults.map((it) => (
                        <button key={it.id} onClick={() => addExtraItem(order, it.id)} style={{ display: "block", width: "100%", textAlign: "left", padding: "8px 12px", border: "none", borderBottom: "1px solid #F5F5F3", background: "#fff", fontSize: 12, cursor: "pointer", fontFamily: "inherit" }}>
                          {it.name} <span style={{ color: "#BBB", fontSize: 10 }}>({it.unit})</span>
                        </button>
                      ))}
                    </div>
                  )}
                </div>
              )}
            </div>
            </>}
          </div>
          {/* Dispatch button — sticky at page bottom, outside overflow card */}
          {orderOpen && (
          <div style={{ position: "sticky", bottom: 0, padding: "8px 0", background: "linear-gradient(transparent, #FAF9F6 20%)", zIndex: 10 }}>
              <button onClick={() => doDispatch(order)} disabled={dispatching === order.id || checkedCount === 0}
                style={{ width: "100%", padding: "14px", borderRadius: 14, border: "none", background: checkedCount === 0 ? "#D0D0CC" : dispatching === order.id ? "#D0D0CC" : checkedCount < itemEntries.length ? "#B45309" : "#16A34A", color: "#fff", fontWeight: 800, fontSize: 16, cursor: checkedCount === 0 || dispatching === order.id ? "not-allowed" : "pointer", fontFamily: "inherit" }}>
                {dispatching === order.id ? "⏳ Dispatching..." : checkedCount === 0 ? "✅ Tick items to dispatch" : checkedCount < itemEntries.length ? `🚚 Dispatch ${checkedCount}/${itemEntries.length} items to ${outlet?.name}` : `🚚 Dispatch All to ${outlet?.name}`}
              </button>
          </div>
          )}
          </div>
        );
      };
      return (<>
        {freshPending.map(renderOrderCard)}
        {oldPending.length > 0 && (
          <div style={{ marginBottom: 10 }}>
            <div onClick={() => setShowOldBacklog((v) => !v)} style={{ padding: "10px 14px", borderRadius: 12, background: "#FFFBEB", border: "1px solid #FDE68A", display: "flex", justifyContent: "space-between", alignItems: "center", cursor: "pointer" }}>
              <span style={{ fontSize: 12, fontWeight: 800, color: "#B45309" }}>⚠️ {oldPending.length} Old Undispatched Challan{oldPending.length === 1 ? "" : "s"}</span>
              <span style={{ fontSize: 11, color: "#B45309" }}>{showOldBacklog ? "▲ hide" : "▼ show"}</span>
            </div>
            {showOldBacklog && <div style={{ marginTop: 10 }}>{oldPending.map(renderOrderCard)}</div>}
          </div>
        )}
      </>); })()}

      {/* ── DISPATCHED ── date-selectable so old challans stay reachable, not just today's */}
      <div style={{ marginTop: 24 }}>
        <div style={{ fontSize: 14, fontWeight: 700, marginBottom: 10, color: "#16A34A" }}>
          ✅ Dispatched · {selDate === today() ? "Today" : selDate === istDateAgo(1) ? "Yesterday" : selDate}
        </div>
        <div style={{ display: "flex", gap: 6, marginBottom: 12, overflowX: "auto", paddingBottom: 4, alignItems: "center" }}>
          {Array.from({ length: 7 }, (_, i) => {
            const d = istDateAgo(i);
            const label = i === 0 ? "Today" : i === 1 ? "Yesterday" : d.slice(5);
            return (<button key={i} onClick={() => setSelDate(d)} style={{ padding: "7px 14px", borderRadius: 8, fontSize: 12, fontWeight: selDate === d ? 700 : 500, border: selDate === d ? "none" : "1px solid #E0E0DC", cursor: "pointer", fontFamily: "inherit", background: selDate === d ? "#1A1A1A" : "#fff", color: selDate === d ? "#fff" : "#888", whiteSpace: "nowrap", flexShrink: 0 }}>{label}</button>);
          })}
          <input type="date" value={selDate} max={today()} onChange={(e) => e.target.value && setSelDate(e.target.value)} style={{ padding: "6px 10px", borderRadius: 8, fontSize: 12, border: "1px solid #E0E0DC", fontFamily: "inherit", background: "#fff", color: "#555", cursor: "pointer", flexShrink: 0 }} />
        </div>
        {loadingOlder && <div style={{ textAlign: "center", padding: 20, color: "#999", fontSize: 12 }}>⏳ Loading...</div>}
        {!loadingOlder && done.length === 0 && (
          <div style={{ textAlign: "center", padding: 20, color: "#999", fontSize: 12 }}>No dispatches{selOutlet ? ` for ${OUTLETS.find((o) => o.id === selOutlet)?.short}` : ""} on {selDate}</div>
        )}
        {!loadingOlder && done.map((order) => {
          const outlet = findOutletForDisplay(order.outlet_id);
          const hasShortage = order.dispatch_items && order.items && Object.keys(order.items).some((id) => (order.dispatch_items[id] || 0) < (order.items[id] || 0));
          return (
            <div key={order.id} onClick={() => setChallanOrder(order)} style={{ background: hasShortage ? "#FFFBEB" : "#F0FDF4", borderRadius: 12, border: `1px solid ${hasShortage ? "#FDE68A" : "#BBF7D0"}`, padding: "12px 16px", marginBottom: 6, display: "flex", justifyContent: "space-between", alignItems: "center", cursor: "pointer" }}>
              <div style={{ display: "flex", alignItems: "center", gap: 8 }}>
                <span style={{ fontSize: 12, fontWeight: 700 }}>{outlet?.name || order.outlet_id}</span>
                <span style={{ padding: "1px 6px", borderRadius: 3, fontSize: 9, fontWeight: 700, background: hasShortage ? "#FDE68A" : "#DCFCE7", color: hasShortage ? "#B45309" : "#16A34A" }}>{hasShortage ? "PARTIAL" : "FULL"}</span>
              </div>
              <div style={{ display: "flex", alignItems: "center", gap: 6 }}>
                <span style={{ fontSize: 11, color: "#999" }}>{order.dispatched_at ? new Date(order.dispatched_at).toLocaleTimeString("en-IN", { hour: "2-digit", minute: "2-digit", timeZone: "Asia/Kolkata" }) : ""}</span>
                <span style={{ fontSize: 11, color: "#2563EB", fontWeight: 600 }}>📋 Challan →</span>
              </div>
            </div>
          );
        })}
      </div>
    </div>
  );
};

// ═════════════════════════════════════════════════════════════════════════════
//  DRIVER PORTAL — two tabs, kept deliberately simple (large touch targets, no
//  nested menus) since drivers aren't expected to be comfortable with the rest
//  of the app's density.
//  1. Dispatched Challans — read-only, today's fulfilled demands, item comparison.
//  2. Vegetables — today's Vegetable purchase order; driver enters what they
//     actually bought (qty may differ from demanded) and the price paid, with a
//     live per-unit price shown as they type. Saved via PATCH on the purchase
//     order's own items (bought_qty/total_price) — a metadata update only, it
//     never touches inventory_stock, so it's safe to fill in over the course of
//     the day without worrying about "receiving" semantics.
// ═════════════════════════════════════════════════════════════════════════════
const DriverChallans = () => {
  const [orders, setOrders] = useState([]);
  const [loading, setLoading] = useState(true);
  const [openOrder, setOpenOrder] = useState(null);
  const [slotFilter, setSlotFilter] = useState("all"); // all | morning | evening
  useEffect(() => {
    setLoading(true);
    api.getOrders({ date: today(), status: "fulfilled" })
      .then((d) => setOrders((d || []).filter((o) => o.type === "manual")))
      .catch(() => setOrders([]))
      .finally(() => setLoading(false));
  }, []);

  const getName = (id) => getBk(id);
  const getUnit = (id) => bkDisplayUnit(id, BK_ITEMS.find((b) => b.id === id)?.unit || "");

  if (loading) return <div style={{ textAlign: "center", padding: 40, color: "#999", fontSize: 14 }}>⏳ Loading...</div>;

  if (openOrder) {
    const order = openOrder;
    const outlet = findOutletForDisplay(order.outlet_id);
    const demanded = order.items || {};
    const dispatched = order.dispatch_items || demanded;
    const allIds = [...new Set([...Object.keys(demanded), ...Object.keys(dispatched)])].filter((id) => (demanded[id] || 0) > 0 || (dispatched[id] || 0) > 0);
    return (<div>
      <div style={{ display: "flex", alignItems: "center", gap: 10, marginBottom: 16 }}>
        <BackBtn onClick={() => setOpenOrder(null)} />
        <div style={{ flex: 1 }}>
          <div style={{ fontSize: 17, fontWeight: 800 }}>{outlet?.name || order.outlet_id}</div>
          <div style={{ fontSize: 12, color: "#999" }}>{order.date} · {allIds.length} items</div>
        </div>
      </div>
      <div style={{ background: "#fff", borderRadius: 14, border: "1px solid #E8E8E4", overflow: "hidden" }}>
        {allIds.map((id) => {
          const dem = demanded[id] || 0;
          const disp = dispatched[id] || 0;
          const short = disp < dem;
          return (
            <div key={id} style={{ display: "flex", justifyContent: "space-between", alignItems: "center", padding: "14px 16px", borderBottom: "1px solid #F0F0EC" }}>
              <div>
                <div style={{ fontSize: 15, fontWeight: 600 }}>{getName(id)}</div>
                <div style={{ fontSize: 11, color: "#999" }}>{getUnit(id)}{short ? ` · demanded ${dem}` : ""}</div>
              </div>
              <div style={{ fontSize: 18, fontWeight: 800, fontFamily: "'JetBrains Mono'", color: short ? "#DC2626" : "#16A34A" }}>{disp}</div>
            </div>
          );
        })}
      </div>
    </div>);
  }

  const visibleOrders = orders.filter((o) => slotFilter === "all" || o.demand_slot === slotFilter);
  return (<div>
    <div style={{ fontSize: 12, color: "#888", marginBottom: 14 }}>Today's dispatched challans — tap one to see the items</div>
    <div style={{ display: "flex", gap: 8, marginBottom: 14 }}>
      {[{ id: "all", label: "All" }, { id: "morning", label: "🌅 Morning" }, { id: "evening", label: "🌙 Evening" }].map((f) => (
        <button key={f.id} onClick={() => setSlotFilter(f.id)} style={{ flex: 1, padding: "10px", borderRadius: 10, border: slotFilter === f.id ? "none" : "1px solid #E0E0DC", background: slotFilter === f.id ? "#1A1A1A" : "#fff", color: slotFilter === f.id ? "#fff" : "#888", fontWeight: 700, fontSize: 13, cursor: "pointer", fontFamily: "inherit" }}>{f.label}</button>
      ))}
    </div>
    {visibleOrders.length === 0 && <div style={{ textAlign: "center", padding: 40, color: "#999", fontSize: 14 }}>{orders.length === 0 ? "No challans dispatched today yet" : "Nothing for this filter"}</div>}
    {visibleOrders.map((order) => {
      const outlet = findOutletForDisplay(order.outlet_id);
      const itemCount = Object.keys(order.items || {}).filter((id) => (order.items[id] || 0) > 0).length;
      return (
        <div key={order.id} onClick={() => setOpenOrder(order)} style={{ background: "#fff", borderRadius: 14, border: "1px solid #E8E8E4", padding: "16px 18px", marginBottom: 10, display: "flex", justifyContent: "space-between", alignItems: "center", cursor: "pointer" }}>
          <div>
            <div style={{ fontSize: 16, fontWeight: 700 }}>{outlet?.name || order.outlet_id}</div>
            <div style={{ fontSize: 12, color: "#999" }}>{itemCount} items · {order.demand_slot === "morning" ? "🌅 Morning" : "🌙 Evening"}</div>
          </div>
          <span style={{ fontSize: 22, color: "#CCC" }}>→</span>
        </div>
      );
    })}
  </div>);
};

// Stage 6: ported off purchase_orders onto the new Vendor Challans (vendor_challans /
// vendor_challan_items) — the old table stopped getting new Vegetable orders once the
// old Inventory screen's own ordering sub-flow was retired from bk_manager's nav (real
// orders now land here instead, via VendorChallans.jsx's "Order from Vendor"). Same job
// as before: driver enters what was actually bought + total price paid per item: PATCH
// /api/store/challans/:id/items (qty_entered, unit_price — computed from the total paid
// here since that's what a driver actually knows at the market, not a per-kg rate).
// Demanded qty is captured from the FIRST load only (the very qty_entered the challan
// was created with) — after that the driver's save overwrites qty_entered with what was
// actually bought, same as the old order_qty-vs-bought_qty split, just without a
// separate column for it on this newer table.
const DriverVegetables = () => {
  const [challans, setChallans] = useState([]);
  const [demanded, setDemanded] = useState({}); // item_id -> original qty_entered, captured once
  const [loading, setLoading] = useState(true);
  const [editingId, setEditingId] = useState(null);
  const [draftQty, setDraftQty] = useState({});
  const [draftPrice, setDraftPrice] = useState({});
  const [saving, setSaving] = useState(null);
  const [itemError, setItemError] = useState({}); // item_id -> inline error text
  // Same blocking-alert freeze this session already root-caused for Closing Stock/
  // Wastage on a Chef's phone (confirmed via direct DB check: the submission had gone
  // through every time, alert() afterward was the only thing stuck) — a driver reporting
  // "I saved these but they're showing blank" on this exact screen traced to the same
  // thing: alert() here fires *before* any network call on a validation failure, so on a
  // mobile/PWA session that freezes right there, nothing was ever sent to the server, and
  // there's no visible sign the save didn't happen. Toast/inline error replace both alerts.
  const [toast, setToast] = useState(null);
  const Toast = () => toast ? <div style={{ position: "fixed", top: 16, left: "50%", transform: "translateX(-50%)", zIndex: 1000, background: "#16A34A", color: "#fff", padding: "12px 20px", borderRadius: 12, fontSize: 13, fontWeight: 700, textAlign: "center", boxShadow: "0 4px 16px rgba(0,0,0,0.25)", maxWidth: "92%" }}>{toast}</div> : null;

  const load = () => {
    setLoading(true);
    api.getChallans({ date: today(), location: "store", status: "draft" })
      .then((list) => {
        const veg = (list || []).filter((c) => c.vendor_name === "🥬 Vegetables");
        return Promise.all(veg.map((c) => api.getChallan(c.id)));
      })
      .then((full) => {
        setChallans(full);
        setDemanded((prev) => {
          const next = { ...prev };
          full.forEach((c) => (c.items || []).forEach((it) => { if (next[it.item_id] === undefined) next[it.item_id] = it.qty_entered; }));
          return next;
        });
      })
      .catch(() => setChallans([]))
      .finally(() => setLoading(false));
  };
  useEffect(load, []);

  const saveItem = async (challan, item) => {
    const id = item.item_id;
    const qty = Number(draftQty[id] ?? item.qty_entered) || 0;
    const totalPaid = Number(draftPrice[id] ?? item.line_total ?? 0) || 0;
    if (qty <= 0 || totalPaid <= 0) { setItemError((p) => ({ ...p, [id]: "Enter both quantity and price" })); return; }
    setItemError((p) => { const c = { ...p }; delete c[id]; return c; });
    // total_price (what the whole line cost, e.g. "20 Pcs for ₹600") is what the backend's
    // PATCH /items route actually reads to derive and store unit_price/line_total — it
    // was being sent here as `unit_price` instead, a key the backend silently ignores
    // (it only checks patch.total_price), so nothing was ever actually persisted: the
    // Save button updated this component's own local state (looking saved on-screen) but
    // the server-side row kept unit_price/line_total null. Root-caused after a driver
    // reported prices "saved on another phone" reading back blank — confirmed via direct
    // DB check every item's line_total was still null despite qty_entered being correct.
    const unitPrice = Math.round((totalPaid / qty) * 100) / 100;
    setSaving(id);
    try {
      const updated = await api.updateChallanItems(challan.id, { [id]: { qty_entered: qty, total_price: totalPaid } });
      setChallans((prev) => prev.map((c) => (c.id === challan.id ? { ...c, total_amount: updated.total_amount, items: c.items.map((it) => (it.item_id === id ? { ...it, qty_entered: qty, unit_price: unitPrice, line_total: totalPaid } : it)) } : c)));
      setEditingId(null);
      setDraftQty((p) => { const c = { ...p }; delete c[id]; return c; });
      setDraftPrice((p) => { const c = { ...p }; delete c[id]; return c; });
      setToast("✅ Saved");
      setTimeout(() => setToast(null), 1200);
    } catch (e) { setItemError((p) => ({ ...p, [id]: "Error: " + e.message })); }
    finally { setSaving(null); }
  };

  if (loading) return <div style={{ textAlign: "center", padding: 40, color: "#999", fontSize: 14 }}>⏳ Loading...</div>;
  if (challans.length === 0) return <div style={{ textAlign: "center", padding: 40, color: "#999", fontSize: 14 }}>No vegetable order for today yet</div>;

  return (<div><Toast />
    {challans.map((challan) => {
      const items = challan.items || [];
      const doneCount = items.filter((it) => it.unit_price > 0).length;
      return (
        <div key={challan.id} style={{ marginBottom: 20 }}>
          <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center", marginBottom: 10 }}>
            <div style={{ fontSize: 13, fontWeight: 700, color: "#888" }}>🥬 Today's Vegetable Order</div>
            <div style={{ fontSize: 12, fontWeight: 800, color: doneCount === items.length ? "#16A34A" : "#B45309" }}>{doneCount}/{items.length} priced</div>
          </div>
          {items.map((item) => {
            const id = item.item_id;
            const savedDone = item.unit_price > 0;
            const inEdit = editingId === id || !savedDone;
            const savedTotal = item.line_total ?? (item.unit_price > 0 ? Math.round(item.unit_price * item.qty_entered * 100) / 100 : 0);
            if (!inEdit) {
              return (
                <div key={id} style={{ display: "flex", justifyContent: "space-between", alignItems: "center", background: "#F0FDF4", border: "1px solid #BBF7D0", borderRadius: 12, padding: "14px 16px", marginBottom: 8 }}>
                  <div>
                    <div style={{ fontSize: 15, fontWeight: 700 }}>✅ {item.item_name}</div>
                    <div style={{ fontSize: 12, color: "#16A34A", marginTop: 2 }}>{item.qty_entered} {item.unit_entered} for ₹{savedTotal} · ₹{item.unit_price}/{item.unit_entered}</div>
                  </div>
                  <button onClick={() => setEditingId(id)} style={{ padding: "10px 16px", borderRadius: 8, border: "1px solid #BBF7D0", background: "#fff", color: "#16A34A", fontWeight: 700, fontSize: 13, cursor: "pointer", fontFamily: "inherit" }}>✏️ Edit</button>
                </div>
              );
            }
            const q = draftQty[id] ?? item.qty_entered;
            const pr = draftPrice[id] ?? (savedDone ? savedTotal : "");
            const perUnit = q > 0 && pr > 0 ? Math.round((pr / q) * 100) / 100 : 0;
            return (
              <div key={id} style={{ background: "#fff", border: "2px solid #16A34A", borderRadius: 12, padding: "14px 16px", marginBottom: 8 }}>
                <div style={{ fontSize: 16, fontWeight: 700, marginBottom: 2 }}>{item.item_name}</div>
                <div style={{ fontSize: 12, color: "#999", marginBottom: 10 }}>Demanded: {demanded[id] ?? item.qty_entered} {item.unit_entered}</div>
                <div style={{ display: "flex", gap: 8, marginBottom: 8 }}>
                  <div style={{ flex: 1 }}>
                    <div style={{ fontSize: 11, color: "#999", marginBottom: 3 }}>Qty bought ({item.unit_entered})</div>
                    <input type="number" inputMode="decimal" value={q} onChange={(e) => setDraftQty((p) => ({ ...p, [id]: e.target.value }))}
                      style={{ width: "100%", padding: "12px", borderRadius: 10, border: "1px solid #E0E0DC", fontSize: 20, textAlign: "center", fontFamily: "'JetBrains Mono'", fontWeight: 800, boxSizing: "border-box" }} />
                  </div>
                  <div style={{ flex: 1 }}>
                    <div style={{ fontSize: 11, color: "#999", marginBottom: 3 }}>Price paid (₹)</div>
                    <input type="number" inputMode="decimal" value={pr} onChange={(e) => setDraftPrice((p) => ({ ...p, [id]: e.target.value }))} placeholder="₹0"
                      style={{ width: "100%", padding: "12px", borderRadius: 10, border: "1px solid #E0E0DC", fontSize: 20, textAlign: "center", fontFamily: "'JetBrains Mono'", fontWeight: 800, color: "#16A34A", boxSizing: "border-box" }} />
                  </div>
                </div>
                {perUnit > 0 && <div style={{ textAlign: "center", fontSize: 15, fontWeight: 800, color: "#2563EB", marginBottom: 10 }}>≈ ₹{perUnit} / {item.unit_entered}</div>}
                {itemError[id] && <div style={{ textAlign: "center", fontSize: 12, fontWeight: 700, color: "#DC2626", marginBottom: 8 }}>⚠️ {itemError[id]}</div>}
                <button onClick={() => saveItem(challan, item)} disabled={saving === id || !(Number(q) > 0) || !(Number(pr) > 0)} style={{ width: "100%", padding: "13px", borderRadius: 10, border: "none", background: saving === id || !(Number(q) > 0) || !(Number(pr) > 0) ? "#D0D0CC" : "#16A34A", color: "#fff", fontWeight: 800, fontSize: 15, cursor: saving === id || !(Number(q) > 0) || !(Number(pr) > 0) ? "not-allowed" : "pointer", fontFamily: "inherit" }}>
                  {saving === id ? "⏳ Saving..." : "💾 Save"}
                </button>
              </div>
            );
          })}
        </div>
      );
    })}
  </div>);
};

// Shift Manager portal — the restricted screen a shift-manager login lands on. It's exactly
// the outlet manager's Daily Photos capture (Opening / Clean Kitchen / Briefing / Closing),
// scoped to this shift manager's own outlet, and nothing else. OutletPhotoCapture is defined
// later in the file (module-level, so available at render time); no onBack — this IS the app.
const ShiftManagerApp = ({ outlet }) => {
  if (!outlet) return <div style={{ textAlign: "center", padding: 40, color: "#999", fontSize: 13 }}>No outlet is assigned to this login. Ask your manager to fix it.</div>;
  return <OutletPhotoCapture outlet={outlet} onBack={null} />;
};

const DriverPortal = () => {
  const [tab, setTab] = useState("challans");
  return (<div>
    <div style={{ display: "flex", gap: 8, marginBottom: 18 }}>
      <button onClick={() => setTab("challans")} style={{ flex: 1, padding: "18px 10px", borderRadius: 14, border: tab === "challans" ? "none" : "1px solid #E8E8E4", background: tab === "challans" ? "#1A1A1A" : "#fff", color: tab === "challans" ? "#fff" : "#888", fontWeight: 800, fontSize: 14, cursor: "pointer", fontFamily: "inherit", textAlign: "center" }}>🚚<br />Dispatched Challans</button>
      <button onClick={() => setTab("veg")} style={{ flex: 1, padding: "18px 10px", borderRadius: 14, border: tab === "veg" ? "none" : "1px solid #E8E8E4", background: tab === "veg" ? "#16A34A" : "#fff", color: tab === "veg" ? "#fff" : "#888", fontWeight: 800, fontSize: 14, cursor: "pointer", fontFamily: "inherit", textAlign: "center" }}>🥬<br />Vegetables</button>
    </div>
    {tab === "challans" && <DriverChallans />}
    {tab === "veg" && <DriverVegetables />}
  </div>);
};

