        const byOutlet = {};
        (bk.outlets || []).forEach((o) => { byOutlet[o.outlet_id] = { bk: o }; });
        (cons.outlets || []).forEach((o) => { (byOutlet[o.outlet_id] || (byOutlet[o.outlet_id] = {})).cons = o; });
        byDate[ds] = byOutlet;
